import re

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_palindrome(s):
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            return False
        i += 1
        j -= 1
    return True

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    # Check 1: All variable names must be palindromes
    # 排除关键字和函数签名中的变量
    keywords = ['if', 'else', 'for', 'while', 'do', 'switch', 'case', 'break', 'continue', 'return', 'int', 'char', 'bool', 'float', 'double', 'void', 'struct', 'ListNode', 'val', 'next', 'nullptr', 'mergeKLists', 'lists', 'n']
    # 获取所有变量名
    var_pattern = r'\b[a-zA-Z_][a-zA-Z0-9_]*\b'
    for match in re.finditer(var_pattern, code):
        var_name = match.group(0)
        if var_name not in keywords and not var_name.startswith('_'):
            assert is_palindrome(var_name), f"Error: Variable name '{var_name}' is not a palindrome"

    # Check 2: Variable name length must be prime
    for match in re.finditer(var_pattern, code):
        var_name = match.group(0)
        if var_name not in keywords and not var_name.startswith('_'):
            assert is_prime(len(var_name)), f"Error: Variable name '{var_name}' length is not prime"

    # Check 3: At least one variable name must contain a number
    has_number_in_var = False
    for match in re.finditer(var_pattern, code):
        var_name = match.group(0)
        if var_name not in keywords and not var_name.startswith('_'):
            if re.search(r'[0-9]', var_name):
                has_number_in_var = True
                break
    assert has_number_in_var, "Error: No variable name contains a number"

    # Check 4: STL containers are not allowed
    stl_pattern = r'\b(vector|list|map|set|queue|stack|deque|priority_queue)\b'
    assert not re.search(stl_pattern, code), "Error: STL containers are not allowed"

    # Check 5: Each line must end with semicolon (except for braces)
    lines = code.split('\n')
    for line in lines:
        line = line.strip()
        if line and not line.endswith(';') and not line.endswith('{') and not line.endswith('}'):
            assert False, f"Error: Line '{line}' does not end with semicolon"

    # Check 6: Function body must be in one line
    function_body_pattern = r'mergeKLists\([^)]*\)\s*{([^}]*)}'
    match = re.search(function_body_pattern, code, re.DOTALL)
    if match:
        body = match.group(1)
        assert '\n' not in body, "Error: Function body must be in one line"

