import re

def check_instruction(response):
    # 提取代码块或直接使用响应
    if response.strip().startswith("```") and response.strip().endswith("```"):
        code_pattern = r"```.*?\n(.*?)\n```"
        code_match = re.search(code_pattern, response, re.DOTALL)
        if code_match:
            code = code_match.group(1)
        else:
            code = response
    else:
        code = response

    # 检查1：代码必须是单行（不包括函数声明和结尾括号）
    code_implementation = re.sub(r"int count1s\(int num121mun\)\s*\{", "", code)
    code_implementation = re.sub(r"\}\s*$", "", code_implementation)
    lines = [line.strip() for line in code_implementation.split("\n") if line.strip() and not line.strip().startswith("//")]
    assert len(lines) == 1, "Error: Code must be single line"

    # 检查2：变量名必须是回文
    var_pattern = r"[a-zA-Z][a-zA-Z0-9_]*"
    for match in re.finditer(var_pattern, code):
        var = match.group(0)
        # 排除关键字和函数名
        if var not in ["int", "return", "if", "else", "count1s"] and len(var) >= 3:
            assert var == var[::-1], f"Error: Variable '{var}' is not a palindrome"

    # 检查3：变量名必须包含至少一个数字
    # 通常实现这个函数不需要额外变量，所以这个检查可能只适用于函数参数
    # 但我们仍然进行检查
    variable_with_digit = False
    for match in re.finditer(var_pattern, code):
        var = match.group(0)
        if var not in ["int", "return", "if", "else", "count1s"] and re.search(r"[0-9]", var):
            variable_with_digit = True
            break
    assert variable_with_digit, "Error: At least one variable name must contain a digit"

    # 检查4：变量名至少3个字符
    for match in re.finditer(r"\b[a-zA-Z][a-zA-Z0-9_]*\b", code):
        var = match.group(0)
        if var not in ["int", "if", "for"]:  # 排除关键字
            assert len(var) >= 3, f"Error: Variable '{var}' must be at least 3 characters long"

    # 检查5：不允许使用分号（除了函数声明外）
    implementation_code = code_implementation.strip()
    assert ";" not in implementation_code, "Error: No semicolons allowed in implementation"

    print("All format checks passed!")

