import re

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    # Check 1: Methods should be single line
    method_pattern = re.compile(r"(\w+\s*\(.*?\)\s*\{[^;{}]*;?\s*\})|(\w+\s*\(.*?\)\s*:\s*.*?\{[^;{}]*;?\s*\})")
    for match in method_pattern.finditer(code):
        method_body = match.group()
        if method_body.count('\n') > 1:
            raise AssertionError("Methods must be single line (excluding declarations)")

    # Check 2: Variable names should be palindromes
    # Exclude keywords and focus on variable declarations
    var_pattern = re.compile(r"(long long|int|float|double|char|string|bool)\s+([a-zA-Z_][a-zA-Z0-9_]*)")
    for match in var_pattern.finditer(code):
        var = match.group(2)
        if var != var[::-1]:
            raise AssertionError(f"Variable name '{var}' is not a palindrome")

    # Check 3: Class name should start with 'Fib' followed by a palindrome
    class_pattern = re.compile(r"class\s+Fib([a-zA-Z]+)")
    class_match = class_pattern.search(code)
    if not class_match:
        raise AssertionError("Class name must start with 'Fib'")
    else:
        suffix = class_match.group(1)
        if suffix != suffix[::-1]:
            raise AssertionError(f"The part after 'Fib' in class name ('{suffix}') is not a palindrome")

    # Check 4: Numeric constants should be in binary format (excluding those in comments)
    # First remove comments
    code_without_comments = re.sub(r"//.*$", "", code, flags=re.MULTILINE)
    # Then check numeric literals
    number_pattern = re.compile(r"\b(0[xb])?[0-9]+\b")
    for match in number_pattern.finditer(code_without_comments):
        num = match.group()
        if not (num.startswith("0b") or num in ["0", "1"]):
            raise AssertionError(f"Number '{num}' is not in binary format")

    # Check 5: No if statements allowed
    if_pattern = re.compile(r"\bif\b")
    if if_pattern.search(code):
        raise AssertionError("If statements are not allowed")

    # Check 6: Must use ternary operator
    ternary_pattern = re.compile(r"\?.*:.*")
    if not ternary_pattern.search(code):
        raise AssertionError("Must use ternary operator")

