    QueueX queue(2);

    // 测试基本操作
    assert(queue.isEmpty() == true);
    assert(queue.size() == 0);

    assert(queue.enqueue(1) == true);
    assert(queue.size() == 1);
    assert(queue.isEmpty() == false);

    assert(queue.enqueue(2) == true);
    assert(queue.size() == 2);
    assert(queue.isFull() == true);

    // 测试自动扩容
    assert(queue.enqueue(3) == true);
    assert(queue.size() == 3);
    assert(queue.isFull() == false);

    // 测试出队
    size_t value;
    assert(queue.dequeue(value) == true);
    assert(value == 1);
    assert(queue.size() == 2);

    assert(queue.dequeue(value) == true);
    assert(value == 2);

    assert(queue.dequeue(value) == true);
    assert(value == 3);

    assert(queue.isEmpty() == true);
    assert(queue.dequeue(value) == false);

