#include <vector>
#include <atomic>
#include <iostream>

void check_correctness() {
    ThreadSafeCounter counter;

    // 测试基本功能
    assert(counter.get_value() == 0);
    counter.increment();
    assert(counter.get_value() == 1);
    counter.reset();
    assert(counter.get_value() == 0);

    // 测试多线程安全性
    const int num_threads = 10;
    const int iterations = 10000;
    std::vector<std::thread> threads;

    for (int i = 0; i < num_threads; ++i) {
        threads.emplace_back([&counter, iterations]() {
            for (int j = 0; j < iterations; ++j) {
                counter.increment();
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    assert(counter.get_value() == num_threads * iterations);

    // 测试重置功能
    counter.reset();
    assert(counter.get_value() == 0);

    // 测试多线程混合操作
    std::atomic<bool> stop_flag{false};
    std::vector<std::thread> mixed_threads;
    std::atomic<size_t> total_increments{0};

    for (int i = 0; i < num_threads; ++i) {
        mixed_threads.emplace_back([&]() {
            while (!stop_flag) {
                counter.increment();
                total_increments.fetch_add(1, std::memory_order_relaxed);
                counter.get_value();
            }
        });
    }

    std::this_thread::sleep_for(std::chrono::milliseconds(100));
    stop_flag = true;

    for (auto& thread : mixed_threads) {
        thread.join();
    }

    // 验证最终计数器值与总递增次数匹配
    size_t final_count = counter.get_value();
    size_t final_increments = total_increments.load();
    assert(final_count == final_increments);

    std::cout << "All thread safety tests passed!" << std::endl;
}

