    var_pattern = re.compile(r'\b[a-z][a-zA-Z0-9]*\b')
    for match in var_pattern.finditer(code):
        var_name = match.group(0)
        if var_name in ['if', 'int', 'for', 'return', 'bool', 'class', 'public', 'private', 'static', 'unordered_set']:
            continue  # Skip keywords

        # Split into words for camelCase
        words = []
        current_word = ""
        for char in var_name:
            if char.isupper() and current_word:
                words.append(current_word)
                current_word = char.lower()
            else:
                current_word += char
        if current_word:
            words.append(current_word)

        for word in words:
            vowel_count = sum(1 for c in word if c.lower() in 'aeiou')
            assert vowel_count == 1, f"Word '{word}' in variable '{var_name}' does not contain exactly one vowel"

    # Check 2: Variable names should not exceed 12 characters
    var_names = re.findall(r'\b[a-z][a-zA-Z0-9]*\b', code)
    for var_name in var_names:
        if var_name in ['if', 'int', 'for', 'return', 'bool', 'class', 'public', 'private', 'static', 'unordered_set']:
            continue  # Skip keywords
        assert len(var_name) <= 12, f"Variable name '{var_name}' exceeds 12 characters"

    # Check 3: Must use 'static' keyword
    assert "static" in code, "Missing 'static' keyword"

    # Check 4: No numeric literals except 1 and 2
    # This regex looks for digits that aren't 1 or 2
    numbers = re.findall(r'\b[0][0-9]*\b|\b[3-9][0-9]*\b', code)
    assert not numbers, f"Contains numeric literals other than 1 and 2: {numbers}"

    # Check 5: Conditional statements must be on a single line
    # Find all if statements and check if they contain && or || operators spanning multiple lines
    if_blocks = re.findall(r'if\s*\([^)]*\)', code)
    for if_block in if_blocks:
