        assert '||' not in if_block or '\n' not in if_block.split('||')[0], "Conditional with || spans multiple lines"

    # Check 6: Cache container declarations must be on a single line
    declarations = re.findall(r'static\s+unordered_set<[^>]*>[^;]*;', code)
    for decl in declarations:
        assert '\n' not in decl, "Cache container declaration spans multiple lines"

