check_instruction:
import re
import io

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    # 更健壮地提取函数体
    function_pattern = re.compile(r'(\w+\s+\w+\([^)]*\)(?:\s+const)?\s*{)([^}]+)(})')
    function_matches = function_pattern.finditer(code)
    function_bodies = [match.group(2).strip() for match in function_matches]

    # Check 1: Each function body should be a single line
    for body in function_bodies:
        assert body.count(';') <= 1, "Error: Multiple statements in one line"

    # Check 2: Variable names should follow snake_case and include underscores
    snake_case_pattern = re.compile(r'[a-z]+(_[a-z]+)+')
    underscore_pattern = re.compile(r'.*_.*')
    for body in function_bodies:
        if "number_sequence" not in body:
            search_start = 0
            found_valid_var = False
            while True:
                match = snake_case_pattern.search(body, search_start)
                if not match:
                    break
                if underscore_pattern.match(match.group()):
                    found_valid_var = True
                search_start = match.end()
            assert found_valid_var, "Error: Invalid variable naming"

    # Check 3: Function body length should not exceed 60 characters
    for body in function_bodies:
        assert len(body) <= 60, "Error: Function body too long"

    # Check 4: Standard library algorithms should not be used
    banned_algorithms = [
        "count_if", "find", "transform", "sort", "remove",
        "unique", "reverse", "rotate", "shuffle", "partition"
    ]
    for body in function_bodies:
        for algo in banned_algorithms:
            assert algo not in body, "Error: Using banned algorithm function"

    # Check 5: Should not contain additional private members
    class_code = re.search(r'class NumberProcessor {.*?}', code, re.DOTALL)
    if class_code:
        private_section = re.search(r'private:(.*?);', class_code.group(0), re.DOTALL)
        if private_section:
            private_content = private_section.group(1).strip()
            assert "vector<int> number_sequence" in private_content and len(private_content.split(';')) <= 2, "Error: Additional private members found"

    print("All format checks passed!")

