using System;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Linq;

public class CheckCorrectness
{
    public static bool check_correctness()
    {
        var counter = new ThreadSafeCounter();

        // Test basic operations
        if (counter.GetCurrentValue() != 0)
            return false;

        counter.Increment();
        if (counter.GetCurrentValue() != 1)
            return false;

        counter.Decrement();
        if (counter.GetCurrentValue() != 0)
            return false;

        // Test history
        var history = counter.GetHistory().ToList();
        if (history.Count != 2)
            return false;
        if (!history[0].Contains("Increment"))
            return false;
        if (!history[1].Contains("Decrement"))
            return false;

        // Test thread safety with counter verification
        var initial_value = counter.GetCurrentValue();
        var tasks = new List<Task>();
        for (int i = 0; i < 1000; i++)
        {
            tasks.Add(Task.Run(() => counter.Increment()));
            tasks.Add(Task.Run(() => counter.Decrement()));
        }

        Task.WaitAll(tasks.ToArray());

        // Verify final value matches initial (since we added and subtracted equal amounts)
        if (counter.GetCurrentValue() != initial_value)
            return false;

        // Test history after concurrent operations (2 from first tests + 2000 from concurrent test)
        if (counter.GetHistory().Count() != 2002)
            return false;

        return true;
    }
}

