            return false;

        // Test case 2: Single node
        TreeNode root2 = new TreeNode(1);
        var result2 = new Solution().GetAllPaths(root2);
        if (!CompareResults(result2, new List<string> { "1" }))
            return false;

        // Test case 3: Complete binary tree
        TreeNode root3 = new TreeNode(1);
        root3.left = new TreeNode(2);
        root3.right = new TreeNode(3);
        root3.left.left = new TreeNode(4);
        root3.left.right = new TreeNode(5);
        var result3 = new Solution().GetAllPaths(root3);
        if (!CompareResults(result3, new List<string> { "1->2->4", "1->2->5", "1->3" }))
            return false;

        // Test case 4: Null root
        var result4 = new Solution().GetAllPaths(null);
        if (result4.Count != 0)
            return false;

        return true;
    }

    private static bool CompareResults(IList<string> result, IList<string> expected)
    {
        if (result.Count != expected.Count)
            return false;

        var sortedResult = result.OrderBy(x => x).ToList();
        var sortedExpected = expected.OrderBy(x => x).ToList();

        return !sortedResult.Where((t, i) => t != sortedExpected[i]).Any();
    }
}

