def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    # Extract method bodies
    method_patterns = {
        'constructor': r'public FilterManager\(\)\s*=>\s*(.*?);',
        'add_filter': r'public void AddFilter\(string operator_type, string filter_value\)\s*=>\s*(.*?);',
        'is_operator': r'public bool IsOperatorSupported\(string operator_type\)\s*=>\s*(.*?);',
        'serialize': r'public string SerializeFilters\(\)\s*=>\s*(.*?);'
    }

    methods = {}
    for name, pattern in method_patterns.items():
        match = re.search(pattern, code, re.DOTALL)
        if not match:
            assert False, f"Method {name} is not implemented as expression-bodied member"
        methods[name] = match.group(1)

    # 1. Check for single-line expressions
    for name, body in methods.items():
        assert '\n' not in body, f"Method {name} is not a single-line expression"

    # 2. Check for if statements and loops
    forbidden = ['if(', 'if (', 'for(', 'for (', 'while(', 'while (', 'foreach(', 'foreach (']
    for name, body in methods.items():
        for keyword in forbidden:
            assert keyword not in body, f"Method {name} contains forbidden control structure: {keyword}"

    # 3. Check snake_case naming
    variable_pattern = r'\b[a-z][a-z0-9]*(?:_[a-z0-9]+)*\b'
    for name, body in methods.items():
        # Find all identifiers that could be variables
        possible_vars = re.findall(r'\b[a-zA-Z][a-zA-Z0-9_]*\b', body)
        for var in possible_vars:
            # Skip known C# keywords and types
            if var in ['new', 'string', 'var', 'bool', 'List', 'null', 'true', 'false', 'FilterExpression']:
                continue
            # Skip method calls and properties
            if var.endswith('(') or var[0].isupper():
                continue
            # Check if it's likely a variable and follows snake_case
            if var and not re.fullmatch(variable_pattern, var):
                assert False, f"Variable '{var}' in method {name} doesn't follow snake_case naming convention"

    # 4. Check for exactly one ternary operator in each method body
    for name, body in methods.items():
        question_marks = body.count('?')
        colons = body.count(':')
        assert question_marks == 1 and colons == 1, f"Method {name} must contain exactly one ternary operator"

    # 5. Check for string literals except in IsOperatorSupported
    for name, body in methods.items():
        if name != 'is_operator':
            assert '"' not in body and "'" not in body, f"Method {name} contains string literals"

    # 6. Check line length
    for line in code.split('\n'):
        assert len(line) <= 80, f"Line length exceeds 80 characters: {line}"

