def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags=re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    # 检查方法体部分
    method_body = extract_method_body(code)
    if not method_body:
        return "无法找到方法体"

    # 1. 检查变量名长度
    variable_pattern = r"\b([a-zA-Z_][a-zA-Z0-9_]*)\b"
    matches = re.findall(variable_pattern, method_body)
    exemptions = get_keywords_and_types()
    for match in matches:
        if match not in exemptions and len(match) != 3:
            return f"变量 {match} 长度不是3个字符"

    # 2. 检查运算符和操作数之间是否有空格
    if re.search(r"[+\-*/=<>!]=?\s+|\s+[+\-*/=<>!]=?", method_body):
        return "运算符和操作数之间存在空格"

    # 3. 检查行长度（50个字符）
    lines = method_body.split('\n')
    for line in lines:
        trimmed_line = line.strip()
        if trimmed_line and not trimmed_line.strip().startswith("return"):
            if len(trimmed_line) != 50:
                return f"行长度不是50个字符: {trimmed_line}"

    # 4. 检查局部变量数量
    local_vars = re.findall(r"\b(var|string|int|bool|List<[^>]+>)\s+([a-zA-Z_][a-zA-Z0-9_]*)\b", method_body)
    local_var_names = [var[1] for var in local_vars]
    if len(set(local_var_names)) > 3:
        return "局部变量超过3个"

    # 5. 检查是否存在注释
    if "//" in method_body or "/*" in method_body:
        return "代码中包含注释"

    # 6. 检查行数
    non_empty_lines = [line for line in lines if line.strip()]
    if len(non_empty_lines) != 10:
        return f"方法体行数为 {len(non_empty_lines)}，不是10行"

    return "格式检查通过"

def extract_method_body(code):
    import re
    # 尝试匹配方法体
    match = re.search(r"public\s+static\s+List<string>\s+ExecuteChain\s*\([^)]*\)\s*{(.*?)}", code, re.DOTALL)
    if match:
        return match.group(1).strip()
    return None

def get_keywords_and_types():
    return {
        "var", "int", "bool", "void", "new", "if", "for", "try", "out", "ref",
        "null", "true", "false", "base", "this", "List", "Tuple", "string",
        "class", "using", "public", "private", "static", "return", "foreach",
        "while", "break", "continue", "else", "switch", "case", "default",
        "throw", "catch", "finally", "object", "in", "is", "as", "where",
        "from", "select", "get", "set", "readonly", "virtual", "override",
        "abstract", "sealed", "partial", "const", "event", "delegate", "async",
        "await", "params", "goto", "namespace", "struct", "interface", "enum"
    }

