public static bool CheckInstruction(string code)
{
    // 移除类和方法声明，只保留实现代码
    var implementationCode = code.Split(new[] { "public static (int additions, int deletions) CalculateDiff" }, StringSplitOptions.None)[1];
    implementationCode = implementationCode.Split(new[] { '{', '}' }, StringSplitOptions.RemoveEmptyEntries)[1].Trim();

    // 1. 检查是否只有一行代码
    var codeLines = implementationCode.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
    if (codeLines.Length > 1) return false;

    // 2. 检查是否使用循环
    if (implementationCode.Contains("for") || implementationCode.Contains("while") || implementationCode.Contains("foreach"))
        return false;

    // 3. 检查是否使用if/else语句
    if (implementationCode.Contains("if") || implementationCode.Contains("else"))
        return false;

    // 4. 检查是否使用LINQ方法
    string[] linqMethods = { "Select", "Where", "Zip", "Range", "Count", "Any", "All", "OrderBy", "FirstOrDefault" };
    bool hasLinq = linqMethods.Any(method => implementationCode.Contains(method));
    if (!hasLinq) return false;

    // 5. 检查变量名长度
    var variablePattern = @"\b[a-z][a-zA-Z0-9]{0,}\b";
    var variableMatches = Regex.Matches(implementationCode, variablePattern);
    var keywords = new[] { "var", "new", "int", "string", "return", "true", "false", "null" };
    foreach (Match match in variableMatches)
    {
        if (!keywords.Contains(match.Value) && match.Value.Length != 3)
            return false;
    }

    // 6. 检查lambda表达式数量
    var lambdaCount = Regex.Matches(implementationCode, "=>").Count;
    if (lambdaCount != 2) return false;

    // 7. 检查是否有注释
    if (implementationCode.Contains("//") || implementationCode.Contains("/*"))
        return false;

    return true;
}

