import ast
import re

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    # Parse the code into an AST
    try:
        tree = ast.parse(code)
    except SyntaxError:
        assert False, "Invalid Python syntax"

    # Check if only using list comprehensions, map, filter, etc. and single expressions
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            for stmt in node.body:
                assert isinstance(stmt, ast.Return), "Solution must be a single expression using functional methods"

    # Check for prohibited statements
    for node in ast.walk(tree):
        assert not isinstance(node, ast.If), "No if statements allowed"
        assert not isinstance(node, ast.For), "No for loops allowed"
        assert not isinstance(node, ast.While), "No while loops allowed"
        assert not isinstance(node, (ast.Try, ast.With)), "No try or with statements allowed"

    # Check line length
    lines = code.split('\n')
    for line in lines:
        assert len(line) <= 120, "Line length exceeds 120 characters"

    # Check variable name length
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            assert len(node.id) == 3, "All variable names must be exactly 3 characters long"

    # Check for lambda expressions
    lambda_count = sum(1 for node in ast.walk(tree) if isinstance(node, ast.Lambda))
    assert lambda_count > 0, "Must use at least one lambda expression"

    # Check for comments
    comment_pattern = r'#.*$'
    for line in lines:
        assert not re.search(comment_pattern, line), "Comments are not allowed"

