    {
        // Test 1: Basic registration and notification
        var notifier = new EventNotifier();
        int count1 = 0;
        Action callback1 = () => count1++;
        notifier.Register(callback1);
        notifier.NotifyAll();
        if (count1 != 1) return false;

        // Test 2: Multiple registrations
        int count2 = 0;
        Action callback2 = () => count2++;
        notifier.Register(callback2);
        notifier.NotifyAll();
        if (count1 != 2 || count2 != 1) return false;

        // Test 3: Unregistration
        notifier.Unregister(callback1);
        notifier.NotifyAll();
        if (count1 != 2 || count2 != 2) return false;

        // Test 4: Thread safety test
        var threadSafeNotifier = new EventNotifier();
        int threadCount = 0;
        var tasks = new List<Task>();

        // Register a single callback to increment threadCount
        Action threadCallback = () => Interlocked.Increment(ref threadCount);
        threadSafeNotifier.Register(threadCallback);

        // Create multiple tasks that will concurrently call NotifyAll
        for (int i = 0; i < 100; i++)
        {
            tasks.Add(Task.Run(() => threadSafeNotifier.NotifyAll()));
        }

