{
    public static bool check_correctness() 
    {
        var shortener = new UrlShortener();
        var test_cases = new Dictionary<string, string>
        {
            {"https://www.example.com/path1", null},
            {"https://www.example.com/very/long/path2", null},
            {"https://www.example.com/extremely/long/path/with/many/segments", null},
            {"https://www.short.com", null},
            {"https://www.example.com/path?param=value", null}
        };

        // Test URL shortening and retrieval
        var used_codes = new HashSet<string>();
        foreach (var test_case in test_cases.Keys.ToList())
        {
            string short_code = shortener.ShortenUrl(test_case);

            // Verify short code format
            if (short_code.Length != 6 || 
                !short_code.All(c => char.IsLetterOrDigit(c)))
            {
                Console.WriteLine($"Invalid short code format: {short_code}");
                return false;
            }

            // Check for collisions
            if (!used_codes.Add(short_code))
            {
                Console.WriteLine($"Collision detected for code: {short_code}");
                return false;
            }

            // Store short code
            test_cases[test_case] = short_code;

            // Verify URL retrieval
            string retrieved_url = shortener.GetLongUrl(short_code);
            if (retrieved_url != test_case)
            {
                Console.WriteLine($"URL retrieval failed. Expected: {test_case}, Got: {retrieved_url}");
                return false;
            }
        }

        return true;
    }
}

