public class CheckCorrectness
{
    public static bool check_correctness()
    {
        var codec = new Codec();

        // Test case 1: Normal binary tree
        var root1 = new Codec.TreeNode(1);
        root1.left = new Codec.TreeNode(2);
        root1.right = new Codec.TreeNode(3);
        root1.right.left = new Codec.TreeNode(4);
        root1.right.right = new Codec.TreeNode(5);

        string serialized1 = codec.serialize(root1);
        var deserialized1 = codec.deserialize(serialized1);
        if (!IsSameTree(root1, deserialized1)) return false;

        // Test case 2: Empty tree
        string emptyTreeSerialized = codec.serialize(null);
        var emptyTreeDeserialized = codec.deserialize(emptyTreeSerialized);
        if (!IsSameTree(null, emptyTreeDeserialized)) return false;

        // Test case 3: Single node tree
        var root3 = new Codec.TreeNode(1);
        string serialized3 = codec.serialize(root3);
        var deserialized3 = codec.deserialize(serialized3);
        if (!IsSameTree(root3, deserialized3)) return false;

        // Test case 4: Left-heavy tree
        var root4 = new Codec.TreeNode(1);
        root4.left = new Codec.TreeNode(2);
        root4.left.left = new Codec.TreeNode(3);
        string serialized4 = codec.serialize(root4);
        var deserialized4 = codec.deserialize(serialized4);
        if (!IsSameTree(root4, deserialized4)) return false;

        return true;
    }

    private static bool IsSameTree(Codec.TreeNode p, Codec.TreeNode q)
    {
        if (p == null && q == null) return true;
        if (p == null || q == null) return false;
        return p.val == q.val && 
               IsSameTree(p.left, q.left) && 
               IsSameTree(p.right, q.right);
    }
}

