            // 检查结果格式
            if (!IsValidDeploymentId(result, projectName))
            {
                Console.WriteLine($"Test case failed for project name: {projectName}");
                Console.WriteLine($"Generated ID: {result}");
                return false;
            }

            // 检查唯一性
            string result2 = Solution.GenerateDeploymentId(projectName);
            if (result == result2)
            {
                Console.WriteLine("Generated IDs are not unique");
                return false;
            }
        }
        return true;
    }

    private static bool IsValidDeploymentId(string id, string projectName)
    {
        if (string.IsNullOrEmpty(id)) return false;

        // 处理空或null项目名称的情况
        string expectedProjectName = string.IsNullOrEmpty(projectName) ? "Unknown" : projectName;

        // 分割ID以验证格式
        string[] parts = id.Split('-');
        if (parts.Length != 3) return false;

        // 验证项目名称部分
        if (parts[0] != expectedProjectName) return false;

        // 验证时间戳部分
        string timestamp = parts[1];
        if (timestamp.Length != 14 || !DateTime.TryParseExact(timestamp, "yyyyMMddHHmmss", 
            null, System.Globalization.DateTimeStyles.None, out _))
            return false;

        // 验证随机字符串部分
        string randomPart = parts[2];
        if (randomPart.Length != 5 || !Regex.IsMatch(randomPart, "^[A-Z0-9]{5}$"))
            return false;

        return true;
    }
}

