    private static bool CompareDictionaries(Dictionary<char, int> dict1, Dictionary<char, int> dict2) 
    {
        return dict1.Count == dict2.Count && 
               dict1.All(kvp => dict2.ContainsKey(kvp.Key) && dict2[kvp.Key] == kvp.Value);
    }
