    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    # 1. Count total lines
    lines = code.split('\n')
    assert len(lines) == 15, "Code must be exactly 15 lines"

    # 2. Check semicolons per line
    for line in lines:
        if line.strip():
            assert line.count(';') == 1, "Each line must contain exactly one semicolon"

    # 3. Check variable names length
    import re
    variable_pattern = r"\b[a-zA-Z][a-zA-Z0-9]{2}\b"
    variables = re.findall(variable_pattern, code)
    for variable in variables:
        if variable not in ["int", "Pop", "Top", "Min", "val"]:  # 排除关键字和方法名
            assert len(variable) == 3, f"Variable name '{variable}' must be exactly 3 characters"

    # 4. Check whitespace around operators
    operator_pattern = r"\s[\+\-\*\/\=]\s"
    assert not re.search(operator_pattern, code), "No whitespace allowed around operators"

    # 5. Check indentation
    for line in lines:
        if line.strip() and not (line.startswith("public") or line.startswith("{") or line.startswith("}") or line.startswith("    ")):
            assert False, "Each line must start with 4 spaces for indentation"

    # 6. Check brackets on same line
    for line in lines:
        if '{' in line or '}' in line:
            stripped = line.strip()
            assert stripped == '{' or stripped == '}', "Brackets cannot appear on the same line with other code"

