        if (!TestBufferOverflow(buffer))
            return false;

        // Test case 3: Buffer underflow
        if (!TestBufferUnderflow(buffer))
            return false;

        // Test case 4: Circular behavior
        buffer = new CircularBuffer<int>(3);
        if (!TestCircularBehavior(buffer))
            return false;

        // Test case 5: Different data types
        var stringBuffer = new CircularBuffer<string>(2);
        if (!TestDifferentDataTypes(stringBuffer))
            return false;

