    {
        if (!buffer.TryAdd(1)) return false;
        if (!buffer.TryAdd(2)) return false;

        int result;
        if (!buffer.TryTake(out result)) return false;
        if (result != 1) return false;

        if (!buffer.TryTake(out result)) return false;
        if (result != 2) return false;

