        buffer.TryTake(out result);  // Remove 1

        if (!buffer.TryAdd(4)) return false;  // Should succeed

        buffer.TryTake(out result);
        if (result != 2) return false;

        buffer.TryTake(out result);
        if (result != 3) return false;

        buffer.TryTake(out result);
        if (result != 4) return false;

        return true;
    }

