public class CheckCorrectness
{
    private const double K = 8.99E9;
    private const double EPSILON = 1E-3;

    public static bool check_correctness()
    {
        // Test case 1: Basic field calculation
        var simulator1 = new ElectricFieldSimulator(2);
        simulator1.AddParticle(0, 0, 1E-9);
        simulator1.AddParticle(3, 4, -1E-9);
        var field1 = simulator1.CalculateElectricField(1, 1);

        // 正确计算公式: K * q * (x-x0)/r^3, K * q * (y-y0)/r^3
        // 第一个粒子: (0,0) 带电 1E-9
        // r^2 = (1-0)^2 + (1-0)^2 = 2, r^3 = 2*sqrt(2)
        // 第二个粒子: (3,4) 带电 -1E-9
        // r^2 = (1-3)^2 + (1-4)^2 = 4 + 9 = 13, r^3 = 13*sqrt(13)
        double r1 = Math.Sqrt(2);
        double r2 = Math.Sqrt(13);

        double expectedEx1 = K * 1E-9 * 1 / (r1*r1*r1) - K * 1E-9 * 2 / (r2*r2*r2);
        double expectedEy1 = K * 1E-9 * 1 / (r1*r1*r1) - K * 1E-9 * 3 / (r2*r2*r2);

        if (Math.Abs(field1.EX - expectedEx1) > EPSILON || 
            Math.Abs(field1.EY - expectedEy1) > EPSILON)
            return false;

        // Test case 2: Single particle
        var simulator2 = new ElectricFieldSimulator(1);
        simulator2.AddParticle(0, 0, 2E-9);
        var field2 = simulator2.CalculateElectricField(1, 0);

        // 计算公式应该是 K * q / r^2，方向沿着从粒子指向计算点的向量
        double expectedE2 = K * 2E-9 / 1;
        if (Math.Abs(field2.EX - expectedE2) > EPSILON || 
            Math.Abs(field2.EY) > EPSILON)
            return false;

        // Test case 3: Maximum capacity
        var simulator3 = new ElectricFieldSimulator(3);
        simulator3.AddParticle(0, 0, 1E-9);
        simulator3.AddParticle(1, 0, 1E-9);
        simulator3.AddParticle(0, 1, 1E-9);
        var field3 = simulator3.CalculateElectricField(2, 2);

        // 应该计算具体的期望值而不是简单地检查非零
        double r31 = Math.Sqrt(8); // 距离(0,0)的粒子
        double r32 = Math.Sqrt(5); // 距离(1,0)的粒子
        double r33 = Math.Sqrt(5); // 距离(0,1)的粒子

        double expectedEx3 = K * 1E-9 * 2 / (r31*r31*r31) + 
                            K * 1E-9 * 1 / (r32*r32*r32) + 
                            K * 1E-9 * 2 / (r33*r33*r33);
        double expectedEy3 = K * 1E-9 * 2 / (r31*r31*r31) + 
                            K * 1E-9 * 2 / (r32*r32*r32) + 
                            K * 1E-9 * 1 / (r33*r33*r33);

        if (Math.Abs(field3.EX - expectedEx3) > EPSILON || 
            Math.Abs(field3.EY - expectedEy3) > EPSILON)
            return false;

        // Test case 4: Zero distance (should handle zero distance case)
