public class CheckCorrectness
{
    public static bool check_correctness() {
        Solution solution = new Solution();

        // Test case 1: Delete leaf node
        TreeNode root1 = BuildTree(new int?[] {5,3,6,2,4,null,7});
        TreeNode result1 = solution.DeleteNode(root1, 2);
        if (!ValidateBST(result1) || !CompareTree(result1, BuildTree(new int?[] {5,3,6,null,4,null,7})))
            return false;

        // Test case 2: Delete node with one child
        TreeNode root2 = BuildTree(new int?[] {5,3,6,2,4,null,7});
        TreeNode result2 = solution.DeleteNode(root2, 6);
        if (!ValidateBST(result2) || !CompareTree(result2, BuildTree(new int?[] {5,3,7,2,4})))
            return false;

        // Test case 3: Delete node with two children
        TreeNode root3 = BuildTree(new int?[] {5,3,6,2,4,null,7});
        TreeNode result3 = solution.DeleteNode(root3, 3);
        if (!ValidateBST(result3) || !CompareTree(result3, BuildTree(new int?[] {5,4,6,2,null,null,7})))
            return false;

        // Test case 4: Delete root
        TreeNode root4 = BuildTree(new int?[] {5,3,6,2,4,null,7});
        TreeNode result4 = solution.DeleteNode(root4, 5);
        if (!ValidateBST(result4))
            return false;
        // 验证删除根节点后结果正确
        // 根节点被删除后，可以是6替代，或者4替代
        bool validReplacement = CompareTree(result4, BuildTree(new int?[] {6,3,7,2,4})) || 
                               CompareTree(result4, BuildTree(new int?[] {4,3,6,2,null,null,7}));
        if (!validReplacement)
            return false;

        // Test case 5: Delete non-existent node
        TreeNode root5 = BuildTree(new int?[] {5,3,6,2,4,null,7});
        TreeNode result5 = solution.DeleteNode(root5, 10);
        if (!CompareTree(root5, result5))
            return false;

        return true;
    }

    private static TreeNode BuildTree(int?[] values) {
        if (values == null || values.Length == 0) return null;

        TreeNode root = new TreeNode(values[0].Value);
        Queue<TreeNode> queue = new Queue<TreeNode>();
        queue.Enqueue(root);
        int i = 1;

        while (queue.Count > 0 && i < values.Length) {
            TreeNode node = queue.Dequeue();

            if (i < values.Length && values[i].HasValue) {
                node.left = new TreeNode(values[i].Value);
                queue.Enqueue(node.left);
            }
            i++;

            if (i < values.Length && values[i].HasValue) {
                node.right = new TreeNode(values[i].Value);
                queue.Enqueue(node.right);
            }
            i++;
        }

        return root;
    }

    private static bool ValidateBST(TreeNode root) {
        return ValidateBSTHelper(root, long.MinValue, long.MaxValue);
    }

    private static bool ValidateBSTHelper(TreeNode node, long min, long max) {
        if (node == null) return true;

        if (node.val <= min || node.val >= max)
            return false;

        return ValidateBSTHelper(node.left, min, node.val) && 
               ValidateBSTHelper(node.right, node.val, max);
    }

    private static bool CompareTree(TreeNode t1, TreeNode t2) {
        if (t1 == null && t2 == null) return true;
        if (t1 == null || t2 == null) return false;

        return t1.val == t2.val && 
               CompareTree(t1.left, t2.left) && 
               CompareTree(t1.right, t2.right);
    }
}

