                new Dictionary<string, object>
                {
                    {"Content-Type", "text/html"},
                    {"Set-Cookie", new List<string> {"id=123", "session=abc"}},
                    {"Description", "This is a folded header"}
                }
            )
        };

        foreach (var (input, expected) in test_cases)
        {
            var result = Solution.ParseHeaders(input);

            if (!CompareDictionaries(result, expected))
            {
                Console.WriteLine($"Test failed for input:\n{input}");
                return false;
            }
        }

        return true;
    }

    private static bool CompareDictionaries(Dictionary<string, object> dict1, Dictionary<string, object> dict2)
    {
        if (dict1.Count != dict2.Count) return false;

        foreach (var key in dict1.Keys)
        {
            if (!dict2.ContainsKey(key)) return false;

            if (dict1[key] is List<string> list1 && dict2[key] is List<string> list2)
            {
                if (!list1.SequenceEqual(list2)) return false;
            }
            else if (!dict1[key].Equals(dict2[key])) return false;
        }

        return true;
    }
}

