import re

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags=re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    assert check_camel_case(code), "Variable names should be in camelCase"
    assert check_no_loops(code), "Loops are not allowed"
    assert check_no_regex(code), "Regular expressions are not allowed"
    assert check_no_helper_methods(code), "Helper methods are not allowed"
    assert check_method_length(code), "Method is too long"

def check_camel_case(code):
    # 检查所有变量声明和参数
    local_vars = re.findall(r'(?:int|boolean|String|char)\s+([a-zA-Z][a-zA-Z0-9]*)', code)
    assignments = re.findall(r'(?<!\.|=)\b([a-zA-Z][a-zA-Z0-9]*)\s*=', code)
    all_vars = local_vars + assignments

    for var in all_vars:
        # 排除常量(全大写)
        if not var.isupper() and not re.match(r'[a-z][a-zA-Z0-9]*', var):
            return False
    return True

def check_no_loops(code):
    return not re.search(r'\b(for|while|do)\b', code)

def check_no_regex(code):
    return not re.search(r'\b(Pattern|Matcher|matches|replaceAll|split|regex)\b', code)

def check_no_helper_methods(code):
    # Java 代码检查
    if "public class" in code:
        method_pattern = re.compile(r'(public|private|protected|static|\s) +[\w\<\>\[\]]+\s+(\w+) *\([^\)]*\) *\{', re.MULTILINE)
        methods = method_pattern.findall(code)
        # 只允许有isMatch方法
        if len(methods) > 1 or (len(methods) == 1 and methods[0][1] != "isMatch"):
            return False
        return True
    # Python 代码检查
    else:
        pattern = re.compile(r'def\s+(\w+)\s*\(')
        methods = pattern.findall(code)
        return len(methods) == 1 and methods[0] == "isMatch"

def check_method_length(code):
    if "public class" in code:  # Java代码
        # 提取isMatch方法体
        method_match = re.search(r'public static boolean isMatch\([^\)]+\)\s*\{([^}]*)\}', code, re.DOTALL)
        if not method_match:
            return False

        method_body = method_match.group(1)
        # 计算非空行
        lines = [line for line in method_body.split('\n') if line.strip()]
        return len(lines) <= 15
    else:  # Python代码
        in_method = False
        method_lines = 0
        lines = code.split('\n')

        for line in lines:
            if 'def isMatch' in line:
                in_method = True
                continue
            if in_method and line.strip():
                if line.strip().startswith('def ') or line.strip() == '':
                    in_method = False
                else:
                    method_lines += 1

        return method_lines <= 15

