import re

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    check_method_names(code)
    check_private_vars(code)
    check_method_length(code)
    check_stream_api(code)
    check_class_name(code)

def check_method_names(code):
    pattern = re.compile(r"public\s+\w+\s+(\w+)\s*\(")
    for match in pattern.finditer(code):
        method_name = match.group(1)
        assert re.match(r"^[a-z]+([A-Z][a-z]*)?$", method_name), f"Method name '{method_name}' does not follow naming convention"

def check_private_vars(code):
    pattern = re.compile(r"private\s+\w+\s+(\w+)\s*;")
    for match in pattern.finditer(code):
        var_name = match.group(1)
        assert var_name.startswith("_"), f"Private variable '{var_name}' should start with underscore"

def check_method_length(code):
    # 获取方法定义和实现之间的内容
    methods = re.finditer(r"(public|private|protected)\s+\w+\s+\w+\s*\([^)]*\)\s*\{([^{}]|(?R))*\}", code, re.DOTALL)
    for method in methods:
        method_body = method.group(0)
        # 计算方法体内的行数，减去方法声明和结束括号
        lines = method_body.split("\n")
        content_lines = [line for line in lines if line.strip() and not (line.strip().startswith('{') or line.strip() == '}')]
        assert len(content_lines) <= 10, f"Method body exceeds 10 lines: {len(content_lines)} lines"

def check_stream_api(code):
    # 检查排序方法是否使用了Stream API
    sort_method = re.search(r"public\s+List<Card>\s+sort\s*\([^)]*\)\s*\{([^{}]|(?R))*\}", code, re.DOTALL)
    if sort_method:
        assert re.search(r"\.stream\(\)", sort_method.group(0)), "Sort method should use Stream API"
    else:
        assert "stream()" in code, "Code should use Stream API for sorting"

def check_class_name(code):
