        ListNode result4 = Solution.reorderOddEven(test4);
        assert result4 == null;

        // Test case 5: Two nodes
        ListNode test5 = createList(new int[]{1,2});
        ListNode result5 = Solution.reorderOddEven(test5);
        assert validateList(result5, new int[]{1,2});
    }

    private static ListNode createList(int[] values) {
        if (values.length == 0) return null;
        ListNode head = new ListNode(values[0]);
        ListNode current = head;
        for (int i = 1; i < values.length; i++) {
            current.next = new ListNode(values[i]);
            current = current.next;
        }
        return head;
    }

    private static boolean validateList(ListNode head, int[] expected) {
        int i = 0;
        ListNode current = head;
        while (current != null && i < expected.length) {
            if (current.val != expected[i]) return false;
            current = current.next;
            i++;
        }
        return current == null && i == expected.length;
    }
}

