import re

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    check_string_builder(code)
    check_chinese_numerals(code)
    check_magic_numbers(code)
    check_camel_case_with_verb(code)
    check_indentation(code)

def check_string_builder(code):
    assert "StringBuilder" in code, "StringBuilder not found in code"

def check_chinese_numerals(code):
    assert "第一" in code or "第二" in code or "第三" in code, "Chinese numerals not found in code"

def check_magic_numbers(code):
    # 排除常量定义中出现的数字
    constants = re.findall(r"(private|public|protected)?\s+static\s+final\s+\w+\s+\w+\s*=\s*\d+", code)

    # 找出所有可能的魔法数字
    all_numbers = re.findall(r"(?<!\w)[0-9]+(?!\w)", code)

    # 检查是否所有数字都定义为常量
    for num in all_numbers:
        # 排除在常量定义中出现的数字
        if not any(num in const for const in constants):
            # 检查数字是否可能是合法的非魔法数字(如循环初始化为0等)
            if num != "0" and num != "1":  # 某些场景0和1是允许的
                assert False, f"Magic number {num} found without constant definition"

def check_camel_case_with_verb(code):
    # 排除类名、方法名等必要的非变量标识符
    variable_pattern = re.compile(r"(?:int|float|double|String|StringBuilder|char|boolean)\s+([a-z][a-zA-Z0-9]*)")
    variables = variable_pattern.findall(code)

    for var in variables:
        assert contains_verb(var), f"Variable {var} does not contain a verb"

def check_indentation(code):
    pattern = re.compile(r"\n\s+")
    matches = pattern.finditer(code)
    for match in matches:
        indent = match.group()
        assert "\t" not in indent and len(indent.strip("\n")) % 3 == 0, "Indentation is not a multiple of 3 spaces or contains tabs"

def contains_verb(var):
    common_verbs = ["get", "set", "add", "remove", "build", "parse", "process", "create", "update", "delete", "find", "append", "convert", "format", "generate", "handle", "make", "print", "read", "write"]
    for verb in common_verbs:
        if verb in var.lower():
            return True
    return False

