import re

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    assert check_single_line_method(code), "Method should be on a single line"
    assert check_camel_case_verb(code), "Method names should be camelCase starting with a verb"
    assert check_single_stream(code), "Only one stream operation allowed per method"
    assert check_no_utility_classes(code), "Utility classes should not be used"
    assert check_comment_style(code), "Only // comments are allowed, not /* */"
    return True

def check_single_line_method(code):
    # 查找方法体并检查是否包含换行
    methods = re.findall(r"public\s+\w+\s+\w+\([^)]*\)\s*\{[^}]*\}", code)
    for method in methods:
        if "\n" in method:
            return False
    return True

def check_camel_case_verb(code):
    # 找出所有变量名
    var_pattern = re.compile(r"\b[a-z][a-zA-Z0-9]*\b")
    # 排除关键字和基本类型
    keywords = ["public", "private", "protected", "static", "final", "void", "int", "boolean", "String", "double", "float", "long", "char", "byte", "short", "return", "if", "else", "for", "while", "do", "switch", "case", "break", "continue", "new", "true", "false", "null", "this", "super", "class", "interface", "enum", "extends", "implements", "import", "package", "try", "catch", "finally", "throw", "throws", "instanceof"]

    variables = []
    for match in var_pattern.finditer(code):
        var = match.group()
        if var not in keywords and not var.startswith("//"):
            variables.append(var)

    for var in variables:
        # 检查是否符合驼峰命名且第一个单词是动词
        if not var[0].islower():
            return False

        # 找出第一个大写字母的位置，确定第一个单词
        first_upper_index = next((i for i, c in enumerate(var) if c.isupper()), len(var))
        first_word = var[:first_upper_index]

        if not is_verb(first_word) and len(first_word) > 0:  # 忽略空字符串
            return False

    return True

def check_single_stream(code):
    # 查找方法体
    methods = re.findall(r"public\s+\w+\s+\w+\([^)]*\)\s*\{[^}]*\}", code)
    for method in methods:
        # 计算stream操作的数量
        stream_count = method.count(".stream()") + method.count(".Stream()")
        if stream_count > 1:
            return False
    return True

def check_no_utility_classes(code):
    utility_classes = ["Collections", "Arrays"]
    for util in utility_classes:
        if f"{util}." in code:
            return False
    return not re.search(r"\b[A-Z][a-z]*Util\b", code)

def check_comment_style(code):
    # 检查是否有多行注释
    if "/*" in code or "*/" in code:
        return False
    # 确认有单行注释
    return "//" in code

def is_verb(word):
    # 常见动词列表
    verbs = ["get", "set", "add", "remove", "execute", "update", "create", "delete", 
             "find", "search", "sort", "process", "calculate", "validate", "verify", 
             "check", "is", "has", "can", "should", "will", "do", "make", "run", 
             "start", "stop", "pause", "resume", "fetch", "put", "post", "send", "receive"]
    return word.lower() in verbs

