class TestCases {
    public static void checkCorrectness() {
        Solution solution = new Solution();

        // Test case 1: Normal case
        ListNode test1 = new ListNode(4);
        test1.next = new ListNode(2);
        test1.next.next = new ListNode(1);
        test1.next.next.next = new ListNode(3);
        ListNode result1 = solution.sortList(test1);
        assert checkSorted(result1);
        assert checkSameElements(new int[]{1, 2, 3, 4}, result1);

        // Test case 2: Already sorted
        ListNode test2 = new ListNode(1);
        test2.next = new ListNode(2);
        test2.next.next = new ListNode(3);
        ListNode result2 = solution.sortList(test2);
        assert checkSorted(result2);
        assert checkSameElements(new int[]{1, 2, 3}, result2);

        // Test case 3: Empty list
        assert solution.sortList(null) == null;

        // Test case 4: Single node
        ListNode test4 = new ListNode(1);
        ListNode result4 = solution.sortList(test4);
        assert result4.val == 1 && result4.next == null;
    }

    private static boolean checkSorted(ListNode head) {
        if (head == null || head.next == null) return true;
        ListNode current = head;
        while (current.next != null) {
            if (current.val > current.next.val) return false;
            current = current.next;
        }
        return true;
    }

    private static boolean checkSameElements(int[] expected, ListNode head) {
        // Count frequencies in expected array
        java.util.Map<Integer, Integer> expectedCount = new java.util.HashMap<>();
        for (int val : expected) {
            expectedCount.put(val, expectedCount.getOrDefault(val, 0) + 1);
        }

        // Count frequencies in result list
        java.util.Map<Integer, Integer> actualCount = new java.util.HashMap<>();
        ListNode current = head;
        int nodeCount = 0;
        while (current != null) {
            actualCount.put(current.val, actualCount.getOrDefault(current.val, 0) + 1);
            current = current.next;
            nodeCount++;
        }

        // Check if lengths match
        if (nodeCount != expected.length) return false;

        // Check if frequencies match
        return expectedCount.equals(actualCount);
    }
}

