import re

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    assert check_camel_case(code), "Variable names should be in camelCase"
    assert check_recursion(code), "Code should contain recursion"
    assert check_no_extra_data_structures(code), "Code should not use extra data structures"
    assert check_comments(code), "Code should have at least 3 comments"
    assert check_no_helper_methods(code), "Code should not have helper methods"
    assert check_indentation(code), "Code should have proper indentation"

def check_camel_case(code):
    pattern = re.compile(r'\b[a-z][a-zA-Z0-9]*\b')
    variables = pattern.findall(code)
    # 排除保留关键字和方法名
    keywords = ["public", "private", "protected", "static", "void", "int", "boolean", 
                "return", "if", "else", "while", "for", "null", "true", "false", "this", 
                "new", "sortList"]
    for var in variables:
        if var not in keywords and not re.match(r'[a-z][a-zA-Z0-9]*', var):
            return False
    return True

def check_recursion(code):
    # 检查是否至少有一次对sortList的递归调用
    return "sortList(" in code and code.find("sortList(") != code.rfind("sortList(")

def check_no_extra_data_structures(code):
    # 检查是否使用了额外的数据结构
    data_structures = ["ArrayList", "List", "Set", "Map", "HashMap", "HashSet", "[]", "new Array"]
    return not any(ds in code for ds in data_structures)

def check_comments(code):
    # 检查是否有至少3个有意义的注释
    pattern = re.compile(r'//.*|/\*.*?\*/', re.DOTALL)
    comments = pattern.findall(code)
    return len(comments) >= 3

def check_no_helper_methods(code):
    # 确保只有一个方法(sortList)
    pattern = re.compile(r'public.*?\{', re.DOTALL)
    methods = pattern.findall(code)
    return len(methods) == 1 and "sortList" in methods[0]

def check_indentation(code):
    # 检查每行缩进是否为4的倍数
    lines = code.split('\n')
    for line in lines:
        if line.strip() and line[0] == ' ':
            indent = len(line) - len(line.lstrip())
            if indent % 4 != 0:
                return False
    return True

