    var_pattern = re.compile(r'\b(double|int|boolean|String|char)\s+([a-zA-Z][a-zA-Z0-9]*)\b')
    for match in var_pattern.finditer(code):
        var_name = match.group(2)
        # 排除m_开头的成员变量
        if var_name.startswith("m_"):
            continue
        # 检查是否符合驼峰命名法（小写字母开头）
        if not (var_name[0].islower() and not '_' in var_name):
            return False
    return True

def check_member_prefix(code):
    pattern = re.compile(r'private.*?\s+([a-zA-Z_][a-zA-Z0-9_]*)')
    for match in pattern.finditer(code):
        var = match.group(1)
        if not var.startswith("m_"):
            return False
    return True

def check_verb_method_names(code):
    pattern = re.compile(r'public.*?\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(')
    for match in pattern.finditer(code):
        method = match.group(1)
        if not re.match(r'(get|set|add|subtract|multiply|divide|modulo).*', method):
            return False
    return True

def check_no_control_statements(code):
    return not re.search(r'\b(if|else|switch|case|for|while|do)\b', code)

