import re

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    check_uppercase_vars(code)
    check_function_count(code)
    check_function_length(code)
    check_string_constants(code)

def check_uppercase_vars(code):
    pattern = r"\b([a-zA-Z_]\w*)\s*="
    for match in re.finditer(pattern, code):
        var = match.group(1)
        assert var == var.upper(), f"Variable {var} is not uppercase"

def check_function_count(code):
    pattern = r"public\s+\w+\s+\w+\s*\("
    count = len(re.findall(pattern, code))
    assert count == 3, f"Expected 3 functions, found {count}"

def check_function_length(code):
    # 修正函数长度检查
    function_bodies = re.findall(r'public\s+\w+\s+\w+\s*\([^)]*\)\s*{([^{}]*(?:{[^{}]*}[^{}]*)*)}', code)
    for body in function_bodies:
        lines = [line for line in body.split('\n') if line.strip()]
        assert len(lines) <= 10, f"Function exceeds 10 lines: {len(lines)} lines found"

def check_string_constants(code):
    pattern = r"\"([^\"]*)\""
    for match in re.finditer(pattern, code):
        constant = match.group(1)
        assert constant == constant.upper(), f"String constant {constant} is not uppercase"

