import re

def check_instruction(response):
    import re
    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    assert check_variable_prefix(code), "Variable prefix check failed"
    assert check_single_line_method(code), "Single line method check failed"
    assert check_snake_case(code), "Snake case check failed"
    assert check_bitwise_operations(code), "Bitwise operations check failed"
    assert not contains_third_party_imports(code), "Contains third party imports"

def check_variable_prefix(code):
    # 检查所有变量声明和赋值，忽略方法参数和Java关键字
    pattern = re.compile(r'(?:private|protected|public)?\s+\w+\s+([a-zA-Z_]\w*)\s*[;=]|([a-zA-Z_]\w*)\s*=')
    matches = pattern.finditer(code)
    for match in matches:
        var_name = match.group(1) if match.group(1) else match.group(2)
        if var_name and not var_name.startswith('id_') and var_name not in ['int', 'boolean', 'void', 'class', 'public', 'private', 'protected', 'static', 'final']:
            return False
    return True

def check_single_line_method(code):
    # 查找方法体内多于一行代码的情况
    pattern = re.compile(r'\{(?!\s*\})[^{}]*\n\s*[^{}]*\n[^{}]*\}')
    matcher = pattern.search(code)
    return not bool(matcher)

def check_snake_case(code):
    # 检查所有变量声明，忽略Java关键字和类名
    pattern = re.compile(r'(?:private|protected|public)?\s+\w+\s+([a-zA-Z_]\w*)\s*[;=]|([a-zA-Z_]\w*)\s*=')
    matches = pattern.finditer(code)
    for match in matches:
        var_name = match.group(1) if match.group(1) else match.group(2)
        if var_name and var_name not in ['int', 'boolean', 'void', 'class', 'public', 'private', 'protected', 'static', 'final', 'UniqueIDManager']:
            if not re.match(r'^[a-z][a-z0-9_]*$', var_name) or '__' in var_name:
                return False
    return True

def check_bitwise_operations(code):
    return any(op in code for op in ['&', '|', '^', '<<', '>>', '>>>'])

def contains_third_party_imports(code):
    pattern = re.compile(r'import\s+(?!java\.)\w+\.\w+')
    matcher = pattern.search(code)
    return bool(matcher)

