        int[] distribution = new int[24]; // 4! = 24 possible permutations
        int TRIALS = 100000;

        for (int i = 0; i < TRIALS; i++) {
            int[] current = {1, 2, 3, 4}; // Create a fresh array each time
            Solution.shuffle(current);
            int index = getPermutationIndex(current);
            distribution[index]++;
        }

        // Check if distribution is roughly uniform
        double expectedCount = TRIALS / 24.0;
        for (int count : distribution) {
            assert Math.abs(count - expectedCount) / expectedCount < 0.1; // Allow 10% deviation
        }
    }

    private static int getPermutationIndex(int[] arr) {
        int[] temp = arr.clone();
        int index = 0;
        int n = temp.length;
        for (int i = 0; i < n - 1; i++) {
            int position = 0;
            for (int j = i + 1; j < n; j++) {
                if (temp[j] < temp[i]) position++;
            }
            index = index * (n - i) + position;
        }
        return index;
    }
}

