def check_camel_case(code):
    # Busca patrones de variables y asegura que sigan la convención camelCase
    pattern = re.compile(r"\b[a-z][a-zA-Z0-9]*\b")
    matches = pattern.finditer(code)
    for match in matches:
        var = match.group()
        if not re.match(r"^[a-z][a-zA-Z0-9]*$", var):
            return False
    return True

def check_no_loops(code):
    return not re.search(r"\b(for|while|do)\b", code)

def check_recursive(code):
    # Verificar recursión más robustamente - una función que se llama a sí misma
    method_names = re.findall(r"(def|public static|private static)\s+(\w+)", code)
    method_names = [name[1] for name in method_names]

    for name in method_names:
        if name in code.replace(f"def {name}", "").replace(f"public static {name}", "").replace(f"private static {name}", ""):
            return True and "Stack" not in code
    return False

def check_separate_logic(code):
    # Verificar que la lógica de análisis y cálculo esté separada
    if "public static double calculate" in code:  # Java
        return ("private static" in code and "calculate" in code)
    else:  # Python
        return len(re.findall(r"def\s+\w+", code)) >= 2  # Al menos dos funciones definidas

def check_one_liner_number_processing(code):
    # Para Java
    if "public static double calculate" in code:
        pattern = re.compile(
            r"private\s+static\s+double\s+[a-zA-Z]+\s*\([^)]*\)\s*\{[^}]*\}")
        matches = pattern.finditer(code)
        for match in matches:
            method = match.group()
            if ("parseDouble" in method or "parseInt" in method) and len(method.split("\n")) > 3:
                return False
    # Para Python
    else:
        number_processing_lines = []
        lines = code.split("\n")
        for i, line in enumerate(lines):
            if "float(" in line or "int(" in line or "eval(" in line:
                number_processing_lines.append(i)

        # Verificar que cada procesamiento numérico esté en una línea
        for line_num in number_processing_lines:
            if not (lines[line_num].strip().startswith("return") or "=" in lines[line_num]):
                return False

    return True

