    public static void checkCorrectness() {
        Solution solution = new Solution();

        // Test case 1: Standard case
        int[][] board1 = {
            {3,0,6,5,0,8,4,0,0},
            {5,2,0,0,0,0,0,0,0},
            {0,8,7,0,0,0,0,3,1},
