            {0,0,0,0,0,0,0,7,4},
            {0,0,5,2,0,6,3,0,0}
        };
        solution.solveDiagonalSudoku(board1);
        assert isValidDiagonalSudoku(board1);

        // Test case 2: Empty board
        int[][] board2 = new int[9][9];
        solution.solveDiagonalSudoku(board2);
        assert isValidDiagonalSudoku(board2);

        // Test case 3: Nearly complete board
        int[][] board3 = {
            {3,1,6,5,7,8,4,9,2},
            {5,2,9,1,3,4,7,6,8},
            {4,8,7,6,2,9,5,3,1},
            {2,6,3,4,1,5,9,8,7},
            {9,7,4,8,6,3,1,2,5},
            {8,5,1,7,9,2,6,4,0},
            {1,3,8,9,4,7,2,5,6},
            {6,9,2,3,5,1,8,7,4},
            {7,4,5,2,8,6,3,1,0}
        };
        solution.solveDiagonalSudoku(board3);
        assert isValidDiagonalSudoku(board3);
    }

    private static boolean isValidDiagonalSudoku(int[][] board) {
        // Check rows, columns, boxes
        for (int i = 0; i < 9; i++) {
            if (!isValidUnit(board[i]) || 
                !isValidUnit(getColumn(board, i)) || 
                !isValidUnit(getBox(board, i / 3 * 3, i % 3 * 3)))
                return false;
        }

        // Check diagonals
        if (!isValidUnit(getMainDiagonal(board)) || 
            !isValidUnit(getAntiDiagonal(board)))
            return false;

        return true;
    }

    private static boolean isValidUnit(int[] unit) {
        boolean[] seen = new boolean[10];
        for (int num : unit) {
            if (num != 0) {
                if (seen[num]) return false;
                seen[num] = true;
            }
        }
        return true;
    }

    private static int[] getColumn(int[][] board, int col) {
        int[] column = new int[9];
        for (int i = 0; i < 9; i++)
            column[i] = board[i][col];
        return column;
    }

    private static int[] getBox(int[][] board, int row, int col) {
        int[] box = new int[9];
        int idx = 0;
        for (int i = row; i < row + 3; i++)
            for (int j = col; j < col + 3; j++)
                box[idx++] = board[i][j];
        return box;
    }

    private static int[] getMainDiagonal(int[][] board) {
        int[] diagonal = new int[9];
        for (int i = 0; i < 9; i++)
            diagonal[i] = board[i][i];
        return diagonal;
    }

    private static int[] getAntiDiagonal(int[][] board) {
        int[] diagonal = new int[9];
        for (int i = 0; i < 9; i++)
            diagonal[i] = board[i][8-i];
        return diagonal;
    }
}

