def check_method_names(code):
    pattern = re.compile(r"public\s+NumberChain\s+(\w+)\s*\(")
    verbs = ["add", "subtract", "multiply", "divide", "get", "set", "compute", "calculate", "perform", "execute", "run", "do", "make", "create", "build", "generate", "produce", "increment", "decrement", "apply"]
    for match in pattern.finditer(code):
        method_name = match.group(1)
        assert re.match(r"^[a-z]+[A-Za-z]*$", method_name), f"Method name '{method_name}' does not follow camelCase starting with lowercase"
        # Check if method name starts with a verb
        starts_with_verb = False
        for verb in verbs:
            if method_name.startswith(verb):
                starts_with_verb = True
                break
        assert starts_with_verb, f"Method name '{method_name}' does not start with a verb"
    return True

def check_no_math_operators(code):
    pattern = re.compile(r"[^a-zA-Z](\+|-|\*|/|%)(?!=)")
    assert not pattern.search(code), "Mathematical operators found in code"
    return True

def check_single_line_method_bodies(code):
    pattern = re.compile(r"public\s+NumberChain\s+\w+\s*\([^)]*\)\s*\{([^}]*)}")
    for match in pattern.finditer(code):
        body = match.group(1).strip()
        assert len(body.split("\n")) <= 1, "Method body contains multiple lines"
    return True

def check_class_name(code):
    pattern = re.compile(r"class\s+(\w+)\s*\{")
