        ListNode test3 = createList(new int[]{1});
        ListNode result3 = solution.reorderList(test3);
        assert checkOrder(result3, new int[]{1});

        // Test case 4: Empty list
        ListNode test4 = null;
        ListNode result4 = solution.reorderList(test4);
        assert result4 == null;
    }

    private static ListNode createList(int[] values) {
        if (values == null || values.length == 0) return null;
        ListNode dummy = new Solution.ListNode(0);
        ListNode current = dummy;
        for (int val : values) {
            current.next = new Solution.ListNode(val);
            current = current.next;
        }
        return dummy.next;
    }

    private static boolean checkOrder(ListNode head, int[] expected) {
        int i = 0;
        while (head != null && i < expected.length) {
            if (head.val != expected[i]) return false;
            head = head.next;
            i++;
        }
        return head == null && i == expected.length;
    }
}

