def check_camel_case(code):
    # 正确检查驼峰命名法，原代码有误，混用了 match 和 findall
    variable_pattern = re.compile(r'\b[a-z][a-zA-Z0-9]*\b')
    variables = variable_pattern.findall(code)
    for var in variables:
        if not re.match(r'[a-z][a-zA-Z0-9]*', var):
            return False
    return True

def check_ternary_operator(code):
    # if 和 else 可能出现在注释中，这个检查不够严谨
    # 只检查是否有三元运算符也不够，应该检查是否有任何形式的 if 语句
    if re.search(r'\bif\s*\(', code):
        return False
    if "else" in code and not re.search(r'\?.*:.*', code):
        return False
    return True

def check_no_collections(code):
    collections = ["List", "Set", "Map", "Queue", "Stack", "ArrayList", "HashSet", "HashMap"]
    for collection in collections:
        if collection in code:
            return False
    return True

def check_method_length(code):
    # 原代码使用简单的分割方式不准确
    methods = re.findall(r'{\s*\n((?:[^\{\}]*?\n){1,5})\s*}', code)
    for method_body in methods:
        if len(method_body.strip().split('\n')) > 5:
            return False
    return True

def check_variable_names(code):
    # 排除关键词和方法名等
    keywords = ["return", "public", "private", "protected", "static", "void", "int", "boolean", "char", "byte", 
                "short", "long", "float", "double", "String", "class", "new", "null", "true", "false"]

    variable_pattern = re.compile(r'\b[a-z][a-zA-Z0-9]*\b')
    variables = variable_pattern.findall(code)

    for var in variables:
        if var in keywords or var in ["val", "next"]:  # 排除 ListNode 类中预定义的字段
            continue
        # 检查变量名是否包含数据类型
        type_indicators = ["int", "node", "bool", "string", "long", "float", "double", "char", "byte", "list"]
        has_type = any(indicator in var.lower() for indicator in type_indicators)
        if not has_type:
            return False
    return True

