    for line in lines:
        if line.strip() and line.strip() != "{" and line.strip() != "}":
            code_lines += 1
    return code_lines == 1

def check_no_if_else(code):
    return " if " not in code and "else" not in code and "?" not in code

def check_lambda_method_calls(code):
    pattern = re.compile(r"->\\s*([^}]+)")
    matches = pattern.finditer(code)
    for match in matches:
        lambda_body = match.group(1)
        method_call_count = lambda_body.count('.')
        if method_call_count > 2:
            return False
    return True

