    variables = re.findall(r'\b(?!(?:public|private|protected|static|final|void|int|char|boolean|String|class|return|if|else|for|while|new)\b)[a-zA-Z][a-zA-Z0-9]*\b', code)
    for var in variables:
        if not re.match(r'^[a-z][a-zA-Z0-9]*$', var):
            return False
    return True

def check_no_numeric_literals(code):
    return not re.search(r'\b\d+\b', code)

def check_method_references(code):
    # 检查是否包含方法引用，且不包含lambda表达式
    return '::' in code and not re.search(r'->(?!\s*\{)', code)

def check_exactly_one_ternary(code):
    return code.count('?') == 1 and code.count(':') >= 1

