import re
import subprocess

def check_instruction(response):
    # 提取第一个JavaScript代码块
    code_block_match = re.search(r'```javascript(.*?)```', response, re.DOTALL)
    if not code_block_match:
        raise AssertionError("Response does not contain a JavaScript code block.")
    js_code = code_block_match.group(1).strip()

    # 检查函数签名
    if not re.search(r'function\s+parseHTTPVersion\s*\(\s*versionString\s*\)\s*{', js_code):
        raise AssertionError("Function signature is incorrect. Expected 'function parseHTTPVersion(versionString) { ... }'")

    # 检查禁用模式（不使用正则表达式、split、parseInt等）
    disallowed_patterns = [
        r'\.split\(',
        r'parseInt\(',
        r'Number\(',
        r'for\s*\(',
        r'while\s*\(',
        r'/\s*[^/]*\s*/',  # 正则表达式字面量
        r'new\s+RegExp\(',
        r'\.test\(',
        r'\.exec\(',
        r'\.match\(',
    ]
    for pattern in disallowed_patterns:
        if re.search(pattern, js_code):
            raise AssertionError(f"Disallowed pattern detected: {pattern}")

    # 检查递归调用
    if 'parseHTTPVersion(' in js_code:
        raise AssertionError("Recursive calls are not allowed.")

    # 扩展测试用例
    test_cases = [
        ('HTTP/0.9', 9),
        ('HTTP/1.0', 1000),
        ('HTTP/1.1', 1001),
        ('HTTP/2.0', 2000),
        ('HTTP/0.0', 0),
        ('HTTP/9.9', 9999),
        ('HTTP/1.a', -1),
        ('HTTP/a.1', -1),
        ('HTTP/invalid', -1),
        ('HTTP/123', -1),
        ('HTTP/12.3', -1),
    ]

    # 生成测试代码
    test_js = f"""
    {js_code}
    let testCases = {test_cases};
    for (let [input, expected] of testCases) {{
        let result = parseHTTPVersion(input);
        if (result !== expected) {{
            throw new Error(`Test failed for ${{JSON.stringify(input)}}: Expected ${{expected}}, got ${{result}}`);
        }}
    }}
    console.log("All tests passed.");
    """

    # 写入临时文件并执行
    with open("temp.js", "w") as f:
        f.write(test_js)

    try:
        result = subprocess.run(
            ["node", "temp.js"],
            check=True,
            capture_output=True,
            text=True,
            timeout=10
        )
    except subprocess.CalledProcessError as e:
        error_msg = e.stderr or e.stdout
        raise AssertionError(f"Tests failed. Error output:\n{error_msg}")
    except Exception as e:
        raise AssertionError(f"Execution failed: {str(e)}")

    return True

