function check_correctness() {
    const manager = new ExtensionManager();

    // Test 1: Add extensions with dependencies, conflicts, and priorities
    manager.addExtension('ext1', 'Extension 1', [], ['ext2'], 1);
    manager.addExtension('ext2', 'Extension 2', ['ext3'], [], 0);
    manager.addExtension('ext3', 'Extension 3', [], [], 0);
    assert(manager.getExtensionStatus('ext1') === 'inactive', 'Test 1 Failed: ext1 should be inactive');
    assert(manager.getExtensionStatus('ext2') === 'inactive', 'Test 1 Failed: ext2 should be inactive');
    assert(manager.getExtensionStatus('ext3') === 'inactive', 'Test 1 Failed: ext3 should be inactive');

    // Test 2: Attempt to activate ext1 (should fail due to conflict with ext2)
    try {
        manager.activateExtension('ext1');
        assert(false, 'Test 2 Failed: ext1 should not be activated due to conflict with ext2');
    } catch (e) {
        assert(e.message === 'Conflict detected: ext1 cannot be activated while ext2 is active', 'Test 2 Failed: Incorrect error message');
    }

    // Test 3: Attempt to activate ext2 (should fail due to missing dependency ext3)
    try {
        manager.activateExtension('ext2');
        assert(false, 'Test 3 Failed: ext2 should not be activated due to missing dependency ext3');
    } catch (e) {
        assert(e.message === 'Dependency not met: ext3 is not active', 'Test 3 Failed: Incorrect error message');
    }

    // Test 4: Activate ext3 (should succeed)
    manager.activateExtension('ext3');
    assert(manager.getExtensionStatus('ext3') === 'active', 'Test 4 Failed: ext3 should be active');

    // Test 5: Activate ext2 (should succeed now that ext3 is active)
    manager.activateExtension('ext2');
    assert(manager.getExtensionStatus('ext2') === 'active', 'Test 5 Failed: ext2 should be active');

    // Test 6: List all extensions
    const extensions = manager.listExtensions();
