    assert(extensions[1].id === 'ext2' && extensions[1].name === 'Extension 2' && extensions[1].status === 'active', 'Test 6 Failed: ext2 details incorrect');
    assert(extensions[2].id === 'ext3' && extensions[2].name === 'Extension 3' && extensions[2].status === 'active', 'Test 6 Failed: ext3 details incorrect');

    // Test 7: Remove ext2 and check list
    manager.removeExtension('ext2');
    const remainingExtensions = manager.listExtensions();
    assert(remainingExtensions.length === 2, 'Test 7 Failed: There should be 2 extensions left');
    assert(remainingExtensions[0].id === 'ext1', 'Test 7 Failed: ext1 should be the first remaining extension');
    assert(remainingExtensions[1].id === 'ext3', 'Test 7 Failed: ext3 should be the second remaining extension');

    // Test 8: Batch operations
    manager.batchAddExtensions([
        { id: 'ext4', name: 'Extension 4', dependencies: [], conflicts: [], priority: 0 },
        { id: 'ext5', name: 'Extension 5', dependencies: [], conflicts: [], priority: 0 }
    ]);
