    assert(manager.getExtensionStatus('ext5') === 'inactive', 'Test 8 Failed: ext5 should be inactive');
    manager.batchRemoveExtensions(['ext4', 'ext5']);
    assert(manager.listExtensions().length === 2, 'Test 8 Failed: There should be 2 extensions left after batch removal');

