    // Test 3: Check if the role definition includes a description
    assert(customRole.hasOwnProperty('description') && typeof customRole.description === 'string', 'Test 3 Failed: Role definition should include a description');

    // Test 4: Check if the role definition includes an array of actions
    assert(customRole.hasOwnProperty('actions') && Array.isArray(customRole.actions), 'Test 4 Failed: Role definition should include an array of actions');

    // Test 5: Check if the role definition has an "isCustom" property set to true
    assert(customRole.hasOwnProperty('isCustom') && customRole.isCustom === true, 'Test 5 Failed: Role definition should have "isCustom" property set to true');

    // Test 6: Check if the assignable scope is limited to a single subscription ID and it is a valid UUID v4
    assert(customRole.hasOwnProperty('assignableScopes') && Array.isArray(customRole.assignableScopes) && customRole.assignableScopes.length === 1 && uuidv4Regex.test(customRole.assignableScopes[0].split('/').pop()), 'Test 6 Failed: Assignable scope should be limited to a single subscription ID in UUID v4 format');

    // Test 7: Check if the role definition follows camelCase naming convention
    const camelCaseProperties = ['name', 'id', 'isCustom', 'description', 'actions', 'notActions', 'dataActions', 'notDataActions', 'conditions', 'assignableScopes'];
    camelCaseProperties.forEach(prop => {
        assert(customRole.hasOwnProperty(prop), `Test 7 Failed: Property "${prop}" should follow camelCase naming convention`);
    });

    // Test 8: Check if the "notActions" array does not overlap with the "actions" array
    const notActionsOverlap = customRole.notActions.some(action => customRole.actions.includes(action));
    assert(!notActionsOverlap, 'Test 8 Failed: "notActions" array should not overlap with "actions" array');

    // Test 9: Check if the "conditions" object contains at least one condition
    assert(customRole.hasOwnProperty('conditions') && Object.keys(customRole.conditions).length > 0, 'Test 9 Failed: Role definition should contain at least one condition');

    // Test 10: Check if the "dataActions" array does not overlap with the "actions" array
    const dataActionsOverlap = customRole.dataActions.some(action => customRole.actions.includes(action));
    assert(!dataActionsOverlap, 'Test 10 Failed: "dataActions" array should not overlap with "actions" array');

    // Test 11: Check if the "notDataActions" array does not overlap with the "dataActions" array
    const notDataActionsOverlap = customRole.notDataActions.some(action => customRole.dataActions.includes(action));
