def check_correctness():
    def verify_magic_square(square):
        n = len(square)
        target_sum = n * (n**2 + 1) // 2

        # Check rows
        for row in square:
            if sum(row) != target_sum:
                return False

        # Check columns
        for j in range(n):
            if sum(square[i][j] for i in range(n)) != target_sum:
                return False

        # Check diagonals
        if sum(square[i][i] for i in range(n)) != target_sum:
            return False
        if sum(square[i][n-1-i] for i in range(n)) != target_sum:
            return False

        # Check if all numbers from 1 to n*n are present
        flat = [item for sublist in square for item in sublist]
        if sorted(flat) != list(range(1, n*n + 1)):
            return False

        return True

    # Test case 1: 3x3 magic square
    result = magic_square(3)
    assert verify_magic_square(result), 'Failed for n=3'

    # Test case 2: 5x5 magic square
    result = magic_square(5)
    assert verify_magic_square(result), 'Failed for n=5'

