    code_group = re.search(r"```.*?\n(.*?)\n```", response, flags = re.DOTALL)
    if code_group is not None:
        code = code_group.group(1)
    else:
        code = response

    import re

    def check_list_dict_comprehension(code):
        # 检查是否使用了列表推导式和字典推导式
        has_list_comp = '[' in code and 'for' in code and ']' in code
        has_dict_comp = '{' in code and 'for' in code and '}' in code
        return has_list_comp and has_dict_comp

    def check_no_loops(code):
        # 检查是否使用了for或while循环
        return not re.search(r'\\s(for|while)\\s', code)

    def check_decorator_one_line(code):
        # 检查装饰器函数体是否只有一行
        lines = [line.strip() for line in code.split('\\n') if line.strip()]
        decorator_body = False
        line_count = 0
        for line in lines:
            if line.startswith('def count_calls'):
                decorator_body = True
                continue
            if decorator_body and not line.startswith(' '):
                break
            if decorator_body and not line.startswith('def'):
                line_count += 1
        return line_count == 1

    def check_snake_case(code):
        # 检查变量名是否使用蛇形命名法
        variables = re.findall(r'\\b[a-zA-Z_][a-zA-Z0-9_]*\\s*=', code)
        return all(v.strip('= ').islower() and '_' not in v.strip('= ').upper() for v in variables)

    def check_comments(code):
        # 检查注释是否独占一行
        lines = code.split('\\n')
        for line in lines:
            if '#' in line:
                comment_pos = line.index('#')
                if line[:comment_pos].strip():
                    return False
        return True

    assert check_list_dict_comprehension(code), "Must use both list and dictionary comprehension"
    assert check_no_loops(code), "No for or while loops allowed"
    assert check_decorator_one_line(code), "Decorator function body must be one line"
    assert check_snake_case(code), "Variable names must use snake_case"
    assert check_comments(code), "Comments must be on separate lines"

