check_instruction:
def check_instruction(response):
    # Check line of comment
    comment_count = sum(1 for line in response.split('\n') if line.strip().startswith('#'))
    assert comment_count >= 3, "Test Code comment line count failed"

    # Check for modularity and reusability
    assert 'analyze_ip' in response, "Modularity Test failed"

    # Check for shell script basic coding style with 4 spaces indentation
    for line in response.split('\n'):
        line = line.rstrip()
        if line.strip().startswith('#'):
            continue
        if line.startswith(' ') and not line.startswith('    '):
            assert False, "Indentation Test failed"

    # Check if all variables are in uppercase
    for line in response.split('\n'):
        if '=' in line:
            var_name = line.split('=')[0].strip()
            if any(c.islower() for c in var_name):
                assert False, "Variable naming Test failed"

