    function getPersonAttributes(personId: string, attributes: string[]): Record<string, string> {
        if (!mockDatabase[personId]) {
            throw new Error("PersonNotFound");
        }

        const result: Record<string, string> = {};
        for (const attr of attributes) {
            const keys = attr.split('.');
            let current = mockDatabase[personId];
            for (let i = 0; i < keys.length; i++) {
