function check_correctness() {
    const assert = require("assert");
    const Big = require("big.js");

    const multiplier = new MatrixMultiplier();

    // Test case 1: Valid multiplication
    const matrix1 = [
        [new Big(1), new Big(2)],
        [new Big(3), new Big(4)]
    ];
    const matrix2 = [
        [new Big(5), new Big(6)],
        [new Big(7), new Big(8)]
    ];
    const expectedResult1 = [
        [new Big(19), new Big(22)],
        [new Big(43), new Big(50)]
    ];
    assert.deepStrictEqual(multiplier.multiplyMatrices(matrix1, matrix2), expectedResult1, "Test case 1 failed");

    // Test case 2: Incompatible dimensions
    const matrix3 = [[new Big(1), new Big(2), new Big(3)]];
    assert.throws(() => multiplier.multiplyMatrices(matrix1, matrix3), Error, "Test case 2 failed");

    // Test case 3: Larger matrices
    const matrix4 = [
        [new Big(1), new Big(2), new Big(3)],
        [new Big(4), new Big(5), new Big(6)]
    ];
    const matrix5 = [
        [new Big(7), new Big(8)],
        [new Big(9), new Big(10)],
        [new Big(11), new Big(12)]
    ];
    const expectedResult2 = [
        [new Big(58), new Big(64)],
        [new Big(139), new Big(154)]
    ];
    assert.deepStrictEqual(multiplier.multiplyMatrices(matrix4, matrix5), expectedResult2, "Test case 3 failed");

    // Test case 4: Sparse matrices
    const matrix6 = [
        [new Big(1), new Big(0), new Big(0)],
        [new Big(0), new Big(1), new Big(0)],
        [new Big(0), new Big(0), new Big(1)]
    ];
    const matrix7 = [
        [new Big(1), new Big(2), new Big(3)],
        [new Big(4), new Big(5), new Big(6)],
        [new Big(7), new Big(8), new Big(9)]
    ];
    const expectedResult3 = [
        [new Big(1), new Big(2), new Big(3)],
        [new Big(4), new Big(5), new Big(6)],
        [new Big(7), new Big(8), new Big(9)]
    ];
    assert.deepStrictEqual(multiplier.multiplyMatrices(matrix6, matrix7), expectedResult3, "Test case 4 failed");

    // Test case 5: Parallel computation
    const matrix8 = [
        [new Big(1), new Big(2), new Big(3)],
        [new Big(4), new Big(5), new Big(6)],
        [new Big(7), new Big(8), new Big(9)]
    ];
    const matrix9 = [
        [new Big(1), new Big(0), new Big(0)],
        [new Big(0), new Big(1), new Big(0)],
        [new Big(0), new Big(0), new Big(1)]
    ];
    const expectedResult4 = [
        [new Big(1), new Big(2), new Big(3)],
        [new Big(4), new Big(5), new Big(6)],
        [new Big(7), new Big(8), new Big(9)]
    ];
    assert.deepStrictEqual(multiplier.multiplyMatrices(matrix8, matrix9), expectedResult4, "Test case 5 failed");

    console.log("All tests passed!");
}

