async function check_correctness() {
    const assert = require("assert");

    // Test default cache range
    const a = await IntegerCache.valueOf(42);
    const b = await IntegerCache.valueOf(42);
    assert.strictEqual(a === b, true, "Test failed: Cached objects should be the same");

    // Test non-cached value
    const c = await IntegerCache.valueOf(2000);
    const d = await IntegerCache.valueOf(2000);
    assert.strictEqual(c === d, false, "Test failed: Non-cached objects should be different");

    // Test custom cache range
    await IntegerCache.setCacheRange(-1000, 1000);
    const e = await IntegerCache.valueOf(500);
    const f = await IntegerCache.valueOf(500);
    assert.strictEqual(e === f, true, "Test failed: Cached objects within custom range should be the same");

    // Test clearing cache
    await IntegerCache.clearCache();
    const g = await IntegerCache.valueOf(42);
    const h = await IntegerCache.valueOf(42);
    assert.strictEqual(g === h, true, "Test failed: Cache should be reinitialized after clearing");

    // Test RangeError
    try {
        await IntegerCache.valueOf(2147483648);
        assert.fail("Test failed: Expected RangeError was not thrown");
    } catch (error) {
        assert.strictEqual(error instanceof RangeError, true, "Test failed: Expected RangeError was not thrown");
    }

    // Test cache policy
    await IntegerCache.setCachePolicy('LRU');
    const i = await IntegerCache.valueOf(42);
    const j = await IntegerCache.valueOf(42);
    assert.strictEqual(i === j, true, "Test failed: Cached objects with LRU policy should be the same");

    // Test event listener
    let hitEventFired = false;
    IntegerCache.on('hit', (key) => {
        if (key === 42) {
            hitEventFired = true;
        }
