function check_correctness() {
    const assert = require("assert");

    const router = new Router();

    // Test adding and handling GET route
    router.addRoute('GET', '/home', () => 'Welcome to the home page');
    assert.strictEqual(router.handleRequest('GET', '/home'), 'Welcome to the home page', "Test failed: GET /home");

    // Test adding and handling GET route with parameter
    router.addRoute('GET', '/users/:id', (id: string) => `User profile for ID: ${id}`);
    assert.strictEqual(router.handleRequest('GET', '/users/123'), 'User profile for ID: 123', "Test failed: GET /users/:id");

    // Test adding and handling POST route
    router.addRoute('POST', '/api/data', () => 'Data received');
    assert.strictEqual(router.handleRequest('POST', '/api/data'), 'Data received', "Test failed: POST /api/data");

    // Test adding and handling PUT route with multiple parameters
    router.addRoute('PUT', '/users/:id/posts/:postId', (id: string, postId: string) => `Update post ${postId} for user ${id}`);
    assert.strictEqual(router.handleRequest('PUT', '/users/123/posts/456'), 'Update post 456 for user 123', "Test failed: PUT /users/:id/posts/:postId");

    // Test adding and handling DELETE route with regex parameter
    router.addRoute('DELETE', '/users/:id(\d+)', (id: string) => `Delete user with ID: ${id}`);
    assert.strictEqual(router.handleRequest('DELETE', '/users/123'), 'Delete user with ID: 123', "Test failed: DELETE /users/:id(\d+)");

    // Test adding and handling PATCH route with optional parameter
    router.addRoute('PATCH', '/users/:id?/posts/:postId', (id: string | undefined, postId: string) => `Partial update post ${postId} for user ${id || 'unknown'}`);
    assert.strictEqual(router.handleRequest('PATCH', '/users/posts/456'), 'Partial update post 456 for user unknown', "Test failed: PATCH /users/:id?/posts/:postId");

    // Test handling non-existent route
    assert.strictEqual(router.handleRequest('GET', '/notfound'), '404 Not Found', "Test failed: GET /notfound");

    console.log("All tests passed!");
}

