function check_correctness() {
    const assert = require("assert");

    // Test 1: Basic functionality
    const cache1 = new LocalCache();
    cache1.put("small1", [1, 2, 3], "high");
    cache1.put("small2", [4, 5, 6], "medium");
    assert.deepStrictEqual(cache1.get("small1"), [1, 2, 3], "Test 1 failed: small1 should return [1, 2, 3]");
    assert.deepStrictEqual(cache1.get("small2"), [4, 5, 6], "Test 1 failed: small2 should return [4, 5, 6]");
    assert.strictEqual(cache1.getSize(), 2, "Test 1 failed: cache size should be 2");

    // Test 2: Big item should not be cached
    const cache2 = new LocalCache();
    cache2.put("big", new Array(1001).fill(0));
    assert.strictEqual(cache2.get("big"), undefined, "Test 2 failed: big item should not be cached");
    assert.strictEqual(cache2.getSize(), 0, "Test 2 failed: cache size should be 0");

    // Test 3: LRU eviction policy with priority
    const cache3 = new LocalCache();
    for (let i = 0; i < 100; i++) {
        cache3.put(`key${i}`, [i], i % 3 === 0 ? "high" : i % 3 === 1 ? "medium" : "low");
    }
    cache3.put("key100", [100], "high");
    assert.strictEqual(cache3.get("key0"), [0], "Test 3 failed: key0 should not be evicted due to high priority");
    assert.deepStrictEqual(cache3.get("key100"), [100], "Test 3 failed: key100 should be in cache");
    assert.strictEqual(cache3.getSize(), 100, "Test 3 failed: cache size should be 100");

    // Test 4: Multi-level cache
    const cache4 = new LocalCache();
    for (let i = 0; i < 150; i++) {
        cache4.put(`key${i}`, [i]);
    }
    assert.strictEqual(cache4.get("key0"), undefined, "Test 4 failed: key0 should be evicted to second level cache");
    assert.strictEqual(cache4.getSize(), 100, "Test 4 failed: first level cache size should be 100");

    // Test 5: Dynamic cache level adjustment
    const cache5 = new LocalCache();
    cache5.adjustCacheLevels(85);
