    const generador = new GeneradorContraseñasAleatorias();
    const contraseñas1 = generador.generarListaContraseñas(5, 15);
    assert.strictEqual(contraseñas1.length, 5, "Test failed: Expected 5 passwords");

    // Test case 2: Check if the passwords are of the correct length
    const contraseñas2 = generador.generarListaContraseñas(100, 15);
    contraseñas2.forEach(contraseña => {
        assert.ok(contraseña.length >= 12 && contraseña.length <= 20, "Test failed: Password length out of range");
    });

    // Test case 3: Check if the passwords contain at least one uppercase letter, one lowercase letter, one number, and one special character
    const contraseñas3 = generador.generarListaContraseñas(10, 15);
    const uppercasePattern = /[A-Z]/;
    const lowercasePattern = /[a-z]/;
    const numberPattern = /[0-9]/;
    const specialCharPattern = /[!@#$%^&*]/;
    contraseñas3.forEach(contraseña => {
        assert.ok(uppercasePattern.test(contraseña), "Test failed: Password does not contain an uppercase letter");
        assert.ok(lowercasePattern.test(contraseña), "Test failed: Password does not contain a lowercase letter");
        assert.ok(numberPattern.test(contraseña), "Test failed: Password does not contain a number");
        assert.ok(specialCharPattern.test(contraseña), "Test failed: Password does not contain a special character");
    });

    // Test case 4: Check if the function can generate a large number of unique passwords
    const contraseñas4 = generador.generarListaContraseñas(10000000, 15);
    const uniqueContraseñas = new Set(contraseñas4);
