    // Test case 5: Check if the passwords do not contain three consecutive identical characters
    const contraseñas5 = generador.generarListaContraseñas(100, 15);
    const consecutivePattern = /(.)\1\1/;
    contraseñas5.forEach(contraseña => {
        assert.ok(!consecutivePattern.test(contraseña), "Test failed: Password contains three consecutive identical characters");
    });

    // Test case 6: Check if the passwords do not contain three consecutive increasing or decreasing characters
    const contraseñas6 = generador.generarListaContraseñas(100, 15);
    const increasingPattern = /(abc|bcd|cde|def|efg|fgh|ghi|hij|ijk|jkl|klm|lmn|mno|nop|opq|pqr|qrs|rst|stu|tuv|uvw|vwx|wxy|xyz)/i;
    const decreasingPattern = /(zyx|yxw|xwv|wvu|vut|uts|tsr|srq|rqp|qpo|pon|onm|nml|mlk|lkj|kji|jih|ihg|hgf|gfe|fed|edc|dcb|cba)/i;
    contraseñas6.forEach(contraseña => {
        assert.ok(!increasingPattern.test(contraseña), "Test failed: Password contains three consecutive increasing characters");
        assert.ok(!decreasingPattern.test(contraseña), "Test failed: Password contains three consecutive decreasing characters");
    });

    // Test case 7: Check if the passwords do not contain common password patterns
    const contraseñas7 = generador.generarListaContraseñas(100, 15);
    const commonPatterns = ["password", "123456", "qwerty", "admin", "welcome"];
