function check_correctness() {
    const assert = require("assert");

    // Test case 1: Basic ruleset with one target
    const xmlString1 = `<ruleset name="Example"><target host="example.com"/></ruleset>`;
    const result1 = parseRuleset(xmlString1);
    assert.deepStrictEqual(result1, { name: 'Example', targets: ['example.com'], nestedRulesets: [] }, "Test case 1 failed");

    // Test case 2: Ruleset with multiple targets
    const xmlString2 = `<ruleset name="Test"><target host="test.com"/><target host="www.test.com"/></ruleset>`;
    const result2 = parseRuleset(xmlString2);
    assert.deepStrictEqual(result2, { name: 'Test', targets: ['test.com', 'www.test.com'], nestedRulesets: [] }, "Test case 2 failed");

    // Test case 3: Ruleset with no targets
    const xmlString3 = `<ruleset name="Empty"></ruleset>`;
    const result3 = parseRuleset(xmlString3);
    assert.deepStrictEqual(result3, { name: 'Empty', targets: [], nestedRulesets: [] }, "Test case 3 failed");

    // Test case 4: Ruleset with comments and other tags
    const xmlString4 = `<ruleset name="Complex"><!-- Comment --><target host="complex.com"/><otherTag/><target host="www.complex.com"/></ruleset>`;
    const result4 = parseRuleset(xmlString4);
    assert.deepStrictEqual(result4, { name: 'Complex', targets: ['complex.com', 'www.complex.com'], nestedRulesets: [] }, "Test case 4 failed");

    // Test case 5: Ruleset with nested ruleset
    const xmlString5 = `<ruleset name="Parent"><target host="parent.com"/><ruleset name="Child"><target host="child.com"/></ruleset></ruleset>`;
    const result5 = parseRuleset(xmlString5);
    assert.deepStrictEqual(result5, { name: 'Parent', targets: ['parent.com'], nestedRulesets: [{ name: 'Child', targets: ['child.com'] }] }, "Test case 5 failed");

    // Test case 6: Ruleset with multiple nested rulesets
    const xmlString6 = `<ruleset name="Grandparent"><target host="grandparent.com"/><ruleset name="Parent"><target host="parent.com"/><ruleset name="Child"><target host="child.com"/></ruleset></ruleset></ruleset>`;
    const result6 = parseRuleset(xmlString6);
    assert.deepStrictEqual(result6, { name: 'Grandparent', targets: ['grandparent.com'], nestedRulesets: [{ name: 'Parent', targets: ['parent.com'], nestedRulesets: [{ name: 'Child', targets: ['child.com'] }] }] }, "Test case 6 failed");

    console.log("All tests passed!");
}

