function check_correctness() {
    const assert = require("assert");

    // Test case 1: Swapping numbers
    const x = { value: 5 };
    const y = { value: 10 };
    swap(x, y);
    assert.strictEqual(x.value, 10, "Test failed: x should be 10 after swap");
    assert.strictEqual(y.value, 5, "Test failed: y should be 5 after swap");

    // Test case 2: Swapping strings
    const str1 = { value: "Hola" };
    const str2 = { value: "Mundo" };
    swap(str1, str2);
    assert.strictEqual(str1.value, "Mundo", "Test failed: str1 should be 'Mundo' after swap");
    assert.strictEqual(str2.value, "Hola", "Test failed: str2 should be 'Hola' after swap");

    // Test case 3: Swapping objects
    const obj1 = { value: { name: "Alice" } };
    const obj2 = { value: { name: "Bob" } };
    swap(obj1, obj2);
    assert.deepStrictEqual(obj1.value, { name: "Bob" }, "Test failed: obj1 should be { name: 'Bob' } after swap");
    assert.deepStrictEqual(obj2.value, { name: "Alice" }, "Test failed: obj2 should be { name: 'Alice' } after swap");

    // Test case 4: Swapping arrays
    const arr1 = { value: [1, 2, 3] };
    const arr2 = { value: [4, 5, 6] };
    swap(arr1, arr2);
    assert.deepStrictEqual(arr1.value, [4, 5, 6], "Test failed: arr1 should be [4, 5, 6] after swap");
    assert.deepStrictEqual(arr2.value, [1, 2, 3], "Test failed: arr2 should be [1, 2, 3] after swap");

    // Test case 5: Swapping functions
    const func1 = { value: () => "Hello" };
    const func2 = { value: () => "World" };
    swap(func1, func2);
    assert.strictEqual(func1.value(), "World", "Test failed: func1 should return 'World' after swap");
    assert.strictEqual(func2.value(), "Hello", "Test failed: func2 should return 'Hello' after swap");

    // Test case 6: Swapping Promises
    const promise1 = { value: Promise.resolve("Resolved1") };
    const promise2 = { value: Promise.resolve("Resolved2") };
    swap(promise1, promise2);
    promise1.value.then((val) => assert.strictEqual(val, "Resolved2", "Test failed: promise1 should resolve to 'Resolved2' after swap"));
    promise2.value.then((val) => assert.strictEqual(val, "Resolved1", "Test failed: promise2 should resolve to 'Resolved1' after swap"));

    // Test case 7: Swapping Maps
    const map1 = { value: new Map([[1, "one"]]) };
    const map2 = { value: new Map([[2, "two"]]) };
    swap(map1, map2);
    assert.deepStrictEqual(map1.value, new Map([[2, "two"]]), "Test failed: map1 should be new Map([[2, 'two']]) after swap");
    assert.deepStrictEqual(map2.value, new Map([[1, "one"]]), "Test failed: map2 should be new Map([[1, 'one']]) after swap");

    // Test case 8: Swapping Sets
    const set1 = { value: new Set([1, 2, 3]) };
    const set2 = { value: new Set([4, 5, 6]) };
    swap(set1, set2);
    assert.deepStrictEqual(set1.value, new Set([4, 5, 6]), "Test failed: set1 should be new Set([4, 5, 6]) after swap");
    assert.deepStrictEqual(set2.value, new Set([1, 2, 3]), "Test failed: set2 should be new Set([1, 2, 3]) after swap");

    // Test case 9: Swapping Symbols
    const symbol1 = { value: Symbol("sym1") };
    const symbol2 = { value: Symbol("sym2") };
    swap(symbol1, symbol2);
    assert.strictEqual(symbol1.value.toString(), "Symbol(sym2)", "Test failed: symbol1 should be Symbol(sym2) after swap");
    assert.strictEqual(symbol2.value.toString(), "Symbol(sym1)", "Test failed: symbol2 should be Symbol(sym1) after swap");

    // Test case 10: Swapping nested objects with circular references
    const circular1: any = { value: {} };
    const circular2: any = { value: {} };
    circular1.value.circular = circular1;
    circular2.value.circular = circular2;
    swap(circular1, circular2);
    assert.strictEqual(circular1.value.circular, circular2, "Test failed: circular1 should reference circular2 after swap");
    assert.strictEqual(circular2.value.circular, circular1, "Test failed: circular2 should reference circular1 after swap");

    // Test case 11: Swapping frozen objects
    const frozen1 = { value: Object.freeze({ prop: "frozen1" }) };
    const frozen2 = { value: Object.freeze({ prop: "frozen2" }) };
    swap(frozen1, frozen2);
    assert.deepStrictEqual(frozen1.value, { prop: "frozen2" }, "Test failed: frozen1 should be { prop: 'frozen2' } after swap");
    assert.deepStrictEqual(frozen2.value, { prop: "frozen1" }, "Test failed: frozen2 should be { prop: 'frozen1' } after swap");

    console.log("All tests passed!");
}

