7. 实现一个事件监听机制，允许外部监听库存变化事件。

函数或类签名：

```typescript
class CarInventory {
  constructor();

  addCar(car: Car): void;
  removeCar(id: string): void;
  updateCar(id: string, updatedInfo: Partial<Car>): void;
  getCar(id: string): Car | null;
  getAllCars(): Car[];

  syncWithServer(): Promise<void>;

  undo(): void;
  redo(): void;

  getHistory(startTime: Date, endTime: Date): OperationHistory[];

  on(event: 'add' | 'remove' | 'update', listener: (car: Car) => void): void;
}

interface Car {
  id: string;
  make: string;
  model: string;
  year: number;
  price: number;
}

interface OperationHistory {
  type: 'add' | 'remove' | 'update';
  car: Car;
  timestamp: Date;
}
```

