    // Test case 3: Check if a non-installed app is detected
    const checker3 = new BUNDLECHECKER();
    assert.strictEqual(checker3.IS_INSTALLED("com.example.app"), false, "Test failed: com.example.app should not be installed");

    // Test case 4: Perform Firefox-specific operation
    const checker4 = new BUNDLECHECKER();
    checker4.ADD_BUNDLE("org.mozilla.ios.Firefox", "1.0.0", []);
