    checker5.ADD_BUNDLE("com.apple.WebKit", "2.0.0", ["org.mozilla.ios.Firefox"]);
    assert.strictEqual(checker5.PERFORM_OPERATION("WEBKIT_SPECIFIC"), "WebKit-specific operation performed", "Test failed: WebKit-specific operation should be performed");

    // Test case 6: Perform general operation
