check_correctness:
function check_correctness() {
    const assert = require("assert");

    // Test 1: Basic subscription and broadcast
    const broadcaster = new MessageBroadcaster();
    const gameObject1 = { id: 1, isDestroyed: false };
    const gameObject2 = { id: 2, isDestroyed: false };

    let receivedData1: any = null;
    let receivedData2: any = null;

    broadcaster.subscribe("collision", (data: any) => {
        receivedData1 = data;
    }, gameObject1, 1);

    broadcaster.subscribe("collision", (data: any) => {
        receivedData2 = data;
    }, gameObject2, 2);

    broadcaster.broadcast("collision", "Player hit wall").then(() => {
        assert.strictEqual(receivedData1, "Player hit wall", "Test 1 failed: Object 1 did not receive correct data");
        assert.strictEqual(receivedData2, "Player hit wall", "Test 1 failed: Object 2 did not receive correct data");

        // Test 2: Remove destroyed objects
        gameObject1.isDestroyed = true;
        broadcaster.removeDestroyedObjects();
        return broadcaster.broadcast("collision", "Enemy hit player");
    }).then(() => {
        assert.strictEqual(receivedData1, "Player hit wall", "Test 2 failed: Object 1 should not receive new data after destruction");
        assert.strictEqual(receivedData2, "Enemy hit player", "Test 2 failed: Object 2 did not receive correct data after object 1 was destroyed");

        // Test 3: Unsubscribe
        broadcaster.unsubscribe("collision", gameObject2);
        return broadcaster.broadcast("collision", "Another collision");
    }).then(() => {
        assert.strictEqual(receivedData2, "Enemy hit player", "Test 3 failed: Object 2 should not receive new data after unsubscription");

        // Test 4: Batch subscribe and broadcast
        const gameObject3 = { id: 3, isDestroyed: false };
        let receivedData3: any = null;

        broadcaster.batchSubscribe([
            { messageType: "collision", callback: (data: any) => { receivedData3 = data; }, gameObject: gameObject3, priority: 3 }
        ]);

        return broadcaster.batchBroadcast([
            { messageType: "collision", data: "Batch broadcast 1" },
            { messageType: "collision", data: "Batch broadcast 2" }
        ]);
    }).then(() => {
        assert.strictEqual(receivedData3, "Batch broadcast 2", "Test 4 failed: Object 3 did not receive correct data from batch broadcast");

        console.log("All tests passed!");
    }).catch(err => {
        console.error("Tests failed:", err);
    });
}

