function check_correctness() {
    const assert = require("assert");

    // Test case 1: Grant and check permissions
    const permissions = new UserPermissions();
    permissions.grantPermission(1, "edit", new Date(Date.now() + 86400000)); // 1天后过期
    permissions.grantPermission(1, "delete");
    permissions.grantPermission(2, "publish");

    assert.strictEqual(permissions.hasPermission(1, "edit"), true, "Test failed: User 1 should have 'edit' permission");
    assert.strictEqual(permissions.hasPermission(2, "edit"), false, "Test failed: User 2 should not have 'edit' permission");
    assert.deepStrictEqual(permissions.getAllPermissions(1), ["edit", "delete"], "Test failed: User 1 should have ['edit', 'delete'] permissions");

    // Test case 2: Revoke permission and check
    permissions.revokePermission(1, "delete");
    assert.deepStrictEqual(permissions.getAllPermissions(1), ["edit"], "Test failed: User 1 should have ['edit'] permission after revoking 'delete'");

    // Test case 3: Check non-existent user
    assert.strictEqual(permissions.hasPermission(3, "edit"), false, "Test failed: Non-existent user should not have any permissions");

    // Test case 4: Grant multiple permissions to a user
    permissions.grantPermission(3, "view");
    permissions.grantPermission(3, "comment");
    assert.deepStrictEqual(permissions.getAllPermissions(3), ["view", "comment"], "Test failed: User 3 should have ['view', 'comment'] permissions");

    // Test case 5: Check permission inheritance
    permissions.addPermissionInheritance("admin", "edit");
    permissions.addPermissionInheritance("admin", "delete");
    permissions.grantPermission(4, "admin");
    assert.strictEqual(permissions.hasPermission(4, "edit"), true, "Test failed: User 4 should have 'edit' permission through inheritance");
    assert.strictEqual(permissions.hasPermission(4, "delete"), true, "Test failed: User 4 should have 'delete' permission through inheritance");

    // Test case 6: Check permission groups
    permissions.addPermissionToGroup("content_management", "edit");
    permissions.addPermissionToGroup("content_management", "delete");
    assert.deepStrictEqual(permissions.getPermissionsByGroup("content_management"), ["edit", "delete"], "Test failed: 'content_management' group should contain ['edit', 'delete'] permissions");

    // Test case 7: Check permission logs
