function check_correctness() {
    const assert = require("assert");

    // Test 1: Basic registration and unregistration
    const table1 = new ZNMethodTable(16);
    table1.register(123456);
    table1.register(789012);
    assert.strictEqual(table1.getRegisteredCount(), 2, "Test 1 failed: Expected 2 registered nmethods");
    table1.unregister(123456);
    assert.strictEqual(table1.getRegisteredCount(), 1, "Test 1 failed: Expected 1 registered nmethod after unregister");
    assert.strictEqual(table1.getUnregisteredCount(), 1, "Test 1 failed: Expected 1 unregistered nmethod");

    // Test 2: Resizing when exceeding 70% capacity
    const table2 = new ZNMethodTable(4);
    table2.register(1);
    table2.register(2);
    table2.register(3);
    table2.register(4);
    table2.register(5); // Should trigger resize
    assert.strictEqual(table2.getRegisteredCount(), 5, "Test 2 failed: Expected 5 registered nmethods after resize");

    // Test 3: Shrinking when below threshold
    const table3 = new ZNMethodTable(8);
    table3.register(1);
    table3.register(2);
    table3.register(3);
    table3.register(4);
    table3.register(5);
    table3.register(6);
    table3.unregister(1);
    table3.unregister(2);
    table3.unregister(3);
    table3.unregister(4);
    table3.unregister(5); // Should trigger shrink
    assert.strictEqual(table3.getRegisteredCount(), 1, "Test 3 failed: Expected 1 registered nmethod after shrink");

    // Test 4: Minimum size constraint
    const table4 = new ZNMethodTable(2);
    table4.register(1);
    table4.register(2);
    table4.register(3); // Should trigger resize
    table4.unregister(1);
    table4.unregister(2);
    table4.unregister(3); // Should not shrink below minimum size
    assert.strictEqual(table4.getRegisteredCount(), 0, "Test 4 failed: Expected 0 registered nmethods after unregister");

    console.log("All tests passed!");
}

